#!/usr/bin/env python3
"""D08 typed artifact generator (worker_01 consolidation, finite code executor).

Deterministically assembles, from the frozen D08 v0.6 contract as the ONLY
semantic input:
  * reviews/medical_monitoring_r4_d08_typed_fixture_catalog_v1_20260814.json
    (typed fixture catalog; the three expected-leaf keys are null placeholders
    per contract §12)
  * reviews/medical_monitoring_r4_d08_expected_outcome_oracle_v1_20260814.json
    (independently persisted oracle, loaded as an EXACT-HASH-PINNED IMMUTABLE
    INPUT — this generator never derives, writes or rewrites it)
  * reviews/medical_monitoring_r4_d08_challenge_manifest_registry_v1_20260814.json
    (five-column bijection registry + closed assertion DSL + non-circular
    double-pass replay manifest)

Semantic source of truth (single input, v0.6 re-anchor):
  reviews/medical_monitoring_r4_d08_cross_domain_logic_slice_contract_v0_6_20260814.md
  file SHA-256 == semantic SHA-256 ==
  ff3d3a1bd9844ac8808ca7f9ada1466317763eb883e60d825f15bb3015ac4d64
  (round-6 acceptance record; any leftover v0.5 hash token is rejected below)

Oracle independence (contract §12 + corrective gate ff3d3a1b...): the catalog
leaf keys are null placeholders; the real expected leaves exist ONLY in the
independent oracle. The final generator contains NO decision procedure: it
cannot derive, infer, recompute or rewrite medical expected leaves from
typed_input, disposition, case specs or runtime. It only:
  1. validates the pinned contract/catalog/oracle file hashes and the exact
     catalog/oracle/registry schemas,
  2. validates cross references between the pinned oracle and the catalog
     (identity bijection, disposition label vs leaf summary, grain vs primary
     unit kind, ownership, visibility, positive-evidence invariants, integrity
     fail-closed agreement),
  3. assembles the registry + assertion DSL from the two pinned inputs.
The independent semantic verifier (233-case contract audit, §13.3) lives in
tests/test_d08_artifact_generator.py and does not import this module.

Design decisions recorded for Codex review:
  D1  Catalog case objects carry EXACTLY the 16 frozen §12 case keys (15
      identifiers/routing keys + typed_input). The typed payload is required by
      the acceptance check "catalog contains typed input only".
  D2  `expected_leaf_set / expected_trace_leaf_set / expected_source_leaf_set`
      are frozen `null` placeholders in the catalog. Real leaves exist only in
      the oracle, keyed by oracle_case_id.
  D3  `disposition` is the case's design-intent label (frozen §12 key),
      validated against the oracle leaf summary as a cross reference (both
      persisted values); consume-only cases use disposition "consume_only".
  D4  Anti-overfit fixtures are generated by deterministic surface-token
      mutation of a base fixture (project/table/field-name renames, list order,
      stripped version tokens); substantive semantics and disposition are
      unchanged. Strip-only variants share the base substantive_input_hash.
  D5  `mutation_context.substantive_input_hash` is computed by stripping the
      excluded tokens (run/snapshot/revision/version/wall-clock) before
      canonical JSON hashing (STRIP_KEYS below).
  D6  No oracle decision procedure exists in this module (removed in the
      worker_01 consolidation). The oracle is loaded from the pinned file
      (PINNED_ORACLE_FILE_SHA256); any reseal — even one that recomputes the
      embedded content_hash consistently — changes the file bytes and fails
      closed before assembly. Catalog reseal (spec drift / typed-input
      mutation) fails the pinned catalog file hash before the oracle is loaded,
      so a resealed catalog can never cause oracle rewriting.
  D7  The registry carries the five fixed bijection columns plus per-row
      substantive_input_hash / expected_leaf_set_hash / assertion_program_hash
      (D07 pattern); the assertion DSL is a closed op set (DSL_ASSERTION_OPS),
      pinned by dsl_schema_hash. The replay manifest embeds ONLY external
      artifact hashes (contract/catalog/oracle/generator/dsl_schema); the
      registry's own hash is never embedded (non-circular schema, validated
      exactly by content_hash recomputation, two-pass byte-identical replay and
      the externally pinned registry hashes in the tests). The oracle/registry
      never execute runtime code.
  D8  The generator writes ONLY the catalog and the registry. The oracle path
      is opened read-only; the tests statically prove there is no oracle-write
      path and no D08 runtime import.
"""

