# ---------------------------------------------------------------------------
# Canonical JSON and hashing (proven D06/D07 infrastructure conventions)
# ---------------------------------------------------------------------------
def normalize_value(value: Any) -> Any:
    if isinstance(value, str):
        return unicodedata.normalize("NFC", value)
    if isinstance(value, list):
        return [normalize_value(item) for item in value]
    if isinstance(value, dict):
        return {
            unicodedata.normalize("NFC", str(key)): normalize_value(item)
            for key, item in value.items()
        }
    return value


def canonical_json(value: Any) -> str:
    return json.dumps(
        normalize_value(value),
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    )


def sha256_text(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def sha256_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def content_hash(obj: dict[str, Any], own_hash_key: str = "content_hash") -> str:
    core = {key: item for key, item in obj.items() if key != own_hash_key}
    return sha256_text(canonical_json(core))


def normalize_contract(text: str) -> str:
    return unicodedata.normalize("NFC", text.replace("\r\n", "\n").replace("\r", "\n"))


def validate_contract() -> str:
    """Verify frozen contract file bytes and NFC/LF semantic hash."""
    raw = CONTRACT.read_bytes()
    digest = sha256_bytes(raw)
    if digest != CONTRACT_FILE_SHA256:
        raise SystemExit(f"contract file hash {digest} != pinned {CONTRACT_FILE_SHA256}")
    semantic = sha256_text(normalize_contract(raw.decode("utf-8")))
    if semantic != CONTRACT_SEMANTIC_HASH:
        raise SystemExit(f"contract semantic hash {semantic} != pinned {CONTRACT_SEMANTIC_HASH}")
    return semantic


def strip_substantive(value: Any) -> Any:
    """Remove excluded tokens (run/snapshot/revision/version/wall-clock keys)
    from the typed input before hashing (contract §12 substantive input)."""
    if isinstance(value, dict):
        out: dict[str, Any] = {}
        for key, item in value.items():
            if key in STRIP_KEYS:
                continue
            out[key] = strip_substantive(item)
        return out
    if isinstance(value, list):
        return [strip_substantive(item) for item in value]
    return value


def substantive_input_hash(typed_input: dict[str, Any]) -> str:
    core: dict[str, Any] = {
        key: item for key, item in typed_input.items()
        if key not in ("mutation_context", "anti_overfit_variant")
    }
    return sha256_text(canonical_json(strip_substantive(core)))


# ---------------------------------------------------------------------------
# Small validation primitives
# ---------------------------------------------------------------------------
class D08ArtifactError(Exception):
    def __init__(self, stage: str, error_class: str, message: str) -> None:
        super().__init__(f"[{stage}/{error_class}] {message}")
        self.stage = stage
        self.error_class = error_class


def expect_exact_keys(obj: Any, keys: list[str], label: str) -> None:
    if not isinstance(obj, dict):
        raise D08ArtifactError("schema_parse", "schema_error", f"{label} is not an object")
    full = set(keys)
    present = set(obj)
    if present != full:
        raise D08ArtifactError(
            "schema_parse", "schema_error",
            f"{label} keys {sorted(present)} != exact keys {sorted(full)}",
        )


def require_string(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value:
        raise D08ArtifactError("schema_parse", "schema_error", f"{label} must be a non-empty string")
    return value


def require_enum(value: Any, closed: tuple[str, ...], label: str) -> str:
    if value not in closed:
        raise D08ArtifactError(
            "schema_parse", "schema_error", f"{label} value {value!r} not in closed enum",
        )
    return value


def require_string_list(value: Any, label: str) -> list[str]:
    if not isinstance(value, list) or not all(isinstance(item, str) and item for item in value):
        raise D08ArtifactError("schema_parse", "schema_error", f"{label} must be a list of non-empty strings")
    if len(set(value)) != len(value):
        raise D08ArtifactError("schema_parse", "schema_error", f"{label} contains duplicates")
    return value


def sha256_hex(value: str) -> str:
    return re.fullmatch(r"[0-9a-f]{64}", value)


