def _collect_ids(*sections: list[dict[str, Any]], keys: tuple[str, ...]) -> set[str]:
    ids: set[str] = set()

    def walk(value: Any) -> None:
        if isinstance(value, dict):
            for key, item in value.items():
                if key in keys and isinstance(item, list):
                    ids.update(x for x in item if isinstance(x, str))
                elif key in keys and isinstance(item, str):
                    ids.add(item)
                else:
                    walk(item)
        elif isinstance(value, list):
            for item in value:
                walk(item)

    for section in sections:
        walk(section)
    return ids


def _build_scope(spec: dict[str, Any], project: str = PROJECT_REF,
                 subject: str = SUBJECT_REF) -> dict[str, Any]:
    s = spec.get("scope") or {}
    core = {
        "accepted_snapshot_ref": s.get("snapshot", SNAPSHOT_REF),
        "clinical_event_cutoff": s.get("cutoff", CUTOFF_INSTANT),
        "episode_key": s.get("episode", EPISODE_KEY),
        "lineage_hash": None,
        "monitoring_mode": s.get("mode", MONITORING_MODE),
        "producer_version": s.get("producer_version", "SYN-PV-001"),
        "project_ref": project,
        "run_ref": s.get("run", RUN_REF),
        "scope_binding_id": s.get("scope_binding_id", "SYN-SCOPE-001"),
        "site_ref": s.get("site", SITE_REF),
        "snapshot_as_of": SNAPSHOT_AS_OF,
        "subject_ref": subject,
    }
    core["lineage_hash"] = sha256_text(canonical_json(
        {key: item for key, item in core.items() if key != "lineage_hash"}))
    return core


