def _link_nodes(t1: str = "2026-01-10", t2: str = "2026-01-12",
                c1: str = "in_cutoff", c2: str = "in_cutoff") -> tuple[list[dict], list[dict]]:
    times = [T("SYN-TIME-001", t1), T("SYN-TIME-002", t2)]
    nodes = [
        N("SYN-REC-001", "SYN-STABLE-001", "cm", "treatment_record", time_ref_ids=["SYN-TIME-001"], cutoff=c1),
        N("SYN-REC-002", "SYN-STABLE-002", "ae", "event_record", time_ref_ids=["SYN-TIME-002"], cutoff=c2),
    ]
    return times, nodes


def _link_rule(**kw: Any) -> dict[str, Any]:
    defaults = dict(
        relationship_type="explicit_link", anchor_role="left", evidence_role="right",
        grain="per_left_anchor_slot", cardinality_ref="SYN-CARD-001",
        directionality="directed", producer_domains=["D02", "D01"],
        authority_locator="SYN-AUTH-001", fanout=5, dup_policy="SYN-DUP-001",
        owner_domain="D08", left_constraint="obligation_side",
        right_constraint="counterpart_side",
    )
    defaults.update(kw)
    return _rule("SYN-RULE-LINK-001", **defaults)


def _link_card(**kw: Any) -> dict[str, Any]:
    defaults = dict(left_min=1, left_max=1, right_min=0, right_max=1, unbounded=False,
                    unmatched="positive_missing_required", overmatch="allowed",
                    bidirectional=True, reverse_required=True,
                    grain="per_left_anchor_slot")
    defaults.update(kw)
    return _cardinality("SYN-CARD-001", **defaults)


