def _rev_card(**kw: Any) -> dict[str, Any]:
    defaults = dict(left_min=1, left_max=2, right_min=0, right_max=2, unbounded=False,
                    unmatched="positive_missing_required", overmatch="allowed",
                    bidirectional=True, reverse_required=True, grain="per_left_anchor_slot")
    defaults.update(kw)
    return _cardinality("SYN-CARD-001", **defaults)


def _rev_rule(**kw: Any) -> dict[str, Any]:
    defaults = dict(relationship_type="reverse_cardinality", anchor_role="left",
                    evidence_role="right", grain="per_left_anchor_slot",
                    cardinality_ref="SYN-CARD-001", directionality="bidirectional",
                    producer_domains=["D02", "D01"], authority_locator="SYN-AUTH-001",
                    fanout=5, dup_policy="SYN-DUP-001", owner_domain="D08",
                    left_constraint="obligation_side", right_constraint="counterpart_side")
    defaults.update(kw)
    return _rule("SYN-RULE-REV-001", **defaults)


def _rev_nodes(n: int = 3, t2: str = "2026-01-12", t3: str = "2026-01-13") -> tuple[list[dict], list[dict]]:
    times = [T("SYN-TIME-001", "2026-01-10"), T("SYN-TIME-002", t2), T("SYN-TIME-003", t3)]
    nodes = [N("SYN-REC-001", "SYN-STABLE-001", "cm", "treatment_record", time_ref_ids=["SYN-TIME-001"])]
    for i in range(2, n + 1):
        nodes.append(N(f"SYN-REC-{i:03d}", f"SYN-STABLE-{i:03d}", "ae", "event_record",
                       time_ref_ids=[f"SYN-TIME-{i:03d}"]))
    return times, nodes


