# --- F4 d08_unowned_temporal_impossibility (037-048) -------------------------
def _temporal_rule(**kw: Any) -> dict[str, Any]:
    defaults = dict(relationship_type="temporal_impossibility", anchor_role="left",
                    evidence_role="right", grain="per_left_anchor_slot",
                    cardinality_ref="SYN-CARD-001", directionality="directed",
                    producer_domains=["D01"], authority_locator="SYN-AUTH-001",
                    fanout=5, dup_policy="SYN-DUP-001", owner_domain="D08",
                    shared_precision="day", left_constraint="earlier_operand",
                    right_constraint="later_operand", time_operand_ids=["SYN-TIME-001", "SYN-TIME-002"])
    defaults.update(kw)
    return _rule("SYN-RULE-TEMP-001", **defaults)


def _temporal_card(**kw: Any) -> dict[str, Any]:
    defaults = dict(left_min=1, left_max=1, right_min=1, right_max=1, unbounded=False,
                    unmatched="not_applicable", overmatch="allowed",
                    bidirectional=False, reverse_required=False, grain="per_left_anchor_slot")
    defaults.update(kw)
    return _cardinality("SYN-CARD-001", **defaults)


def _temporal_nodes(t1: dict, t2: dict) -> tuple[list[dict], list[dict]]:
    times = [T("SYN-TIME-001", **t1), T("SYN-TIME-002", **t2)]
    nodes = [N("SYN-REC-001", "SYN-STABLE-001", "cm", "treatment_record", time_ref_ids=["SYN-TIME-001"]),
             N("SYN-REC-002", "SYN-STABLE-002", "ae", "event_record", time_ref_ids=["SYN-TIME-002"])]
    return times, nodes


def _temporal_spec(t1: dict, t2: dict, *, expected: str | None, allowed: list[str] | None = None,
                   disposition: str, mc: str, desc: str, rule_kw: dict | None = None,
                   tz_state: str = "present", precision: str = "day",
                   left_open: str = "closed", right_open: str = "closed",
                   card_kw: dict | None = None, window: dict | None = None,
                   vis: dict[str, Any] | None = None) -> dict[str, Any]:
    times, nodes = _temporal_nodes(t1, t2)
    rkw = dict(rule_kw or {})
    if allowed is not None:
        rkw["allowed"] = allowed
    if window is not None:
        rkw["window"] = window
    ckw = dict(card_kw or {})
    spec: dict[str, Any] = {
        "family": "d08_unowned_temporal_impossibility", "token": "d08_unowned_temporal_impossibility",
        "disposition": disposition, "grain": "per_left_anchor_slot",
        "mutation": {"class": mc, "desc": desc},
        "times": times, "nodes": nodes,
        "rules": [_temporal_rule(**rkw)], "cards": [_temporal_card(**ckw)],
        "temporal": [TC("SYN-TC-001", "SYN-RULE-TEMP-001", "SYN-TIME-001", "SYN-TIME-002",
                        left_open=left_open, right_open=right_open, tz_state=tz_state,
                        precision=precision, expected=expected, allowed=allowed)],
        "coverage": [CV("D01")],
        "route": {"required_producer_domains": ["D01"]},
    }
    if vis is not None:
        spec["vis"] = vis
    return spec


