def _prop_rule(**kw: Any) -> dict[str, Any]:
    defaults = dict(relationship_type="modification_propagation", anchor_role="left",
                    evidence_role="right", grain="per_propagation_derived_object",
                    cardinality_ref="SYN-CARD-001", directionality="directed",
                    producer_domains=["D06"], authority_locator="SYN-AUTH-001",
                    fanout=5, dup_policy="SYN-DUP-001", owner_domain="D08",
                    left_constraint="source_record", right_constraint="derived_object")
    defaults.update(kw)
    return _rule("SYN-RULE-PROP-001", **defaults)


def _prop_card(**kw: Any) -> dict[str, Any]:
    defaults = dict(left_min=1, left_max=1, right_min=1, right_max=1, unbounded=False,
                    unmatched="not_applicable", overmatch="allowed",
                    bidirectional=False, reverse_required=False,
                    grain="per_propagation_derived_object")
    defaults.update(kw)
    return _cardinality("SYN-CARD-001", **defaults)


def _prop_fixture(*, source_rev: str = "SRC-REV-004", declared: str = "SRC-REV-003",
                  actual: str = "SRC-REV-003", changed: list[str] | None = None,
                  consumed: list[str] | None = None, cause: str = "data",
                  dtype: str = "producer_declared_derived_value", derived_id: str = "SYN-DERIVED-001",
                  disp: str, mc: str, desc: str, intersection: list[str] | None = None,
                  old_ref: str | None = None, new_ref: str | None = None,
                  derived_consumed: str | None = None, node_rev: str | None = None,
                  fingerprint: str | None = None, rule_version: str = "1",
                  vis: dict[str, Any] | None = None) -> dict[str, Any]:
    times = [T("SYN-TIME-001", "2026-01-10")]
    dconsumed = derived_consumed if derived_consumed is not None else declared
    changed_fields = changed or []
    consumed_fields = consumed if consumed is not None else changed_fields
    computed_intersection = sorted(set(changed_fields) & set(consumed_fields))
    node = N("SYN-REC-001", "SYN-STABLE-001", "cm", "treatment_record", time_ref_ids=["SYN-TIME-001"],
             revision=node_rev if node_rev is not None else source_rev,
             fields={"dose_amount": 10})
    spec: dict[str, Any] = {
        "family": "d08_propagation_lineage", "token": "d08_propagation_lineage",
        "disposition": disp, "grain": "per_propagation_derived_object",
        "mutation": {"class": mc, "desc": desc},
        "times": times, "nodes": [node],
        "rules": [_prop_rule(version=rule_version)], "cards": [_prop_card()],
        "derived": [DV(derived_id, dtype, consumed=dconsumed)],
        "props": [PR("SYN-PROP-001", "SYN-REC-001", source_rev=source_rev, cause=cause,
                     changed=changed_fields, derived_id=derived_id, declared=declared, actual=actual,
                     intersection=intersection if intersection is not None else computed_intersection,
                     old_ref=old_ref, new_ref=new_ref, fingerprint=fingerprint)],
        "coverage": [CV("D06")],
        "bindings": [BD("SYN-BIND-001", "SYN-PROD-001", purpose="derive", outputs=["derived_value"])],
        "route": {"required_producer_domains": ["D06"]},
    }
    if vis is not None:
        spec["vis"] = vis
    return spec


