def _replace_tokens(value: Any, token_map: dict[str, str]) -> Any:
    if isinstance(value, str):
        out = value
        for old, new in token_map.items():
            out = out.replace(old, new)
        return out
    if isinstance(value, list):
        return [_replace_tokens(item, token_map) for item in value]
    if isinstance(value, dict):
        return {key: _replace_tokens(item, token_map) for key, item in value.items()}
    return value


def _rename_field_keys(value: Any) -> Any:
    if isinstance(value, dict):
        out: dict[str, Any] = {}
        for key, item in value.items():
            if key == "accepted_source_field_values" and isinstance(item, dict):
                out[key] = {f"{k}_syn": v for k, v in item.items()}
            else:
                out[key] = _rename_field_keys(item)
        return out
    if isinstance(value, list):
        return [_rename_field_keys(item) for item in value]
    return value


def mutate_surface(typed: dict[str, Any], mode: str, n: int) -> dict[str, Any]:
    """Deterministic surface-only mutation of a base fixture.

    mode="strip_only": changes ONLY tokens excluded from substantive input
    (run/snapshot/revision/producer-version/authority-version/snapshot-as-of),
    so the variant keeps the base substantive_input_hash.
    mode="surface": additionally renames project/table/file/locator tokens,
    renames non-semantic field keys and reverses list order; substantive hash
    changes but the relation semantic and disposition are unchanged.
    """
    common = {
        "SYN-D08-RUN-001": f"SYN-D08-RUN-OVF-{n}",
        "SYN-D08-SNAP-001": f"SYN-D08-SNAP-OVF-{n}",
        "SYN-PV-001": f"SYN-PV-OVF-{n}",
        "SYN-AV-001": f"SYN-AV-OVF-{n}",
        "2026-07-01T00:00:00+00:00": "2026-07-02T00:00:00+00:00",
    }
    tokens = dict(common)
    if mode == "surface":
        tokens.update({
            "SYN-D08-PROJECT": f"SYN-D08-PROJECT-OVF-{n}",
            "SYN-TBL-A": f"SYN-TBL-OVF-{n}",
            "synthetic_source/dataset_a.json": f"synthetic_source/dataset_ovf_{n}.json",
            "synthetic_file": f"synthetic_file_ovf_{n}",
        })
    mutated = _replace_tokens(typed, tokens)
    if mode == "surface":
        if not mutated.get("propagation_objects"):
            mutated = _rename_field_keys(mutated)
        for key in ("record_nodes", "time_refs", "source_locators", "observed_edges"):
            if isinstance(mutated.get(key), list):
                mutated[key] = list(reversed(mutated[key]))
    return mutated


