def build_consume_only_specs() -> list[dict[str, Any]]:
    specs: list[dict[str, Any]] = []
    for token, owner, domains, kind in CONSUME_ONLY_ROWS:
        for resolvable in (True, False):
            times = [T("SYN-TIME-001", "2026-01-10"), T("SYN-TIME-002", "2026-01-12")]
            nodes = [N("SYN-REC-001", "SYN-STABLE-001", domains[0], "owner_claim_record", time_ref_ids=["SYN-TIME-001"]),
                     N("SYN-REC-002", "SYN-STABLE-002", domains[-1], "owner_claim_counterpart", time_ref_ids=["SYN-TIME-002"])]
            status = "unique" if resolvable else "not_found"
            desc = (f"consume-only adjacency {kind}: owner {owner} owns the claim; D08 verifies explicit refs "
                    f"({'resolvable' if resolvable else 'unresolvable'}) and must generate ZERO D08 medical units, risks and Queries")
            specs.append({
                "family": "consume_only_adjacency", "token": token,
                "disposition": CONSUME_ONLY_DISPOSITION, "grain": "per_left_anchor_slot",
                "mutation": {"class": "consume_only_zero_risk", "desc": desc},
                "times": times, "nodes": nodes,
                "rules": [_rule(f"SYN-RULE-CO-{kind}", relationship_type="consume_only_adjacency",
                                grain="per_left_anchor_slot", cardinality_ref="SYN-CARD-001",
                                directionality="directed", producer_domains=[owner],
                                owner_domain=owner, authority_locator="SYN-AUTH-001",
                                left_constraint="owner_claim_left", right_constraint="owner_claim_right")],
                "cards": [_cardinality("SYN-CARD-001", left_min=1, left_max=1, right_min=0, right_max=1,
                                       unmatched="not_applicable", overmatch="allowed",
                                       bidirectional=False, reverse_required=False)],
                "raw": [RAW("SYN-RAWLINK-001", domain=domains[0], idvarval="SYN-REC-001", relid="REL-001")],
                "resolves": [RES("SYN-RES-001", "SYN-RAWLINK-001", status=status,
                                 materialized=["SYN-REC-001"] if resolvable else [])],
                "coverage": [CV(owner)],
                "route": {"owner_domain": owner, "required_producer_domains": [owner],
                          "source": "upstream_handoff"},
            })
    return specs


