def build_temporal_matrix_specs() -> list[dict[str, Any]]:
    specs: list[dict[str, Any]] = []
    for row in TM_ROWS:
        t1, t2, expected, allowed, disp, mc, desc = row[:7]
        rest = row[7:]
        tz_state = rest[0] if len(rest) > 0 else "present"
        precision = rest[1] if len(rest) > 1 else "day"
        open_l = rest[2] if len(rest) > 2 else "closed"
        open_r = rest[3] if len(rest) > 3 else "closed"
        times = [T("SYN-TIME-001", **t1), T("SYN-TIME-002", **t2)]
        nodes = [N("SYN-REC-001", "SYN-STABLE-001", "cm", "treatment_record", time_ref_ids=["SYN-TIME-001"]),
                 N("SYN-REC-002", "SYN-STABLE-002", "ae", "event_record", time_ref_ids=["SYN-TIME-002"])]
        specs.append({
            "family": "temporal_matrix", "token": "d08_unowned_temporal_impossibility",
            "disposition": disp, "grain": "per_left_anchor_slot",
            "mutation": {"class": mc, "desc": desc},
            "times": times, "nodes": nodes,
            "rules": [_rule("SYN-RULE-TM-001", relationship_type="temporal_matrix",
                            anchor_role="left", evidence_role="right", grain="per_left_anchor_slot",
                            cardinality_ref="SYN-CARD-001", directionality="directed",
                            producer_domains=["D01"], owner_domain="D08",
                            authority_locator="SYN-AUTH-001", shared_precision=precision,
                            expected_relation=expected, allowed=allowed if allowed else None,
                            left_constraint="earlier_operand", right_constraint="later_operand",
                            time_operand_ids=["SYN-TIME-001", "SYN-TIME-002"])],
            "cards": [_cardinality("SYN-CARD-001", left_min=1, left_max=1, right_min=1, right_max=1,
                                   unmatched="not_applicable", overmatch="allowed",
                                   bidirectional=False, reverse_required=False)],
            "temporal": [TC("SYN-TC-001", "SYN-RULE-TM-001", "SYN-TIME-001", "SYN-TIME-002",
                            left_open=open_l, right_open=open_r, tz_state=tz_state,
                            precision=precision, expected=expected, allowed=allowed if allowed else None)],
            "coverage": [CV("D01")],
            "route": {"required_producer_domains": ["D01"]},
        })
    return specs


