def build_identity_matrix_specs() -> list[dict[str, Any]]:
    specs: list[dict[str, Any]] = []
    for (disp, mc, desc, stable_equal, time_equal, content_equal, subject_b, modeling,
         mirror, unknown, site_b, dedup_mismatch, collision) in IDM_ROWS:
        times = [T("SYN-TIME-001", "2026-01-10"), T("SYN-TIME-002", "2026-01-10" if time_equal else "2026-01-12")]
        node_b = {"subject": SUBJECT_REF_2} if subject_b else {}
        if site_b:
            node_b["site"] = "SYN-D08-SITE-002"
        fields_a = {"event_text": "synthetic event text", "result_value": 5} if content_equal else {"event_text": "a"}
        fields_b = {"event_text": "synthetic event text", "result_value": 5} if content_equal else {"event_text": "b"}
        rev_b = "SRC-REV-003" if stable_equal else "SRC-REV-003"
        nodes = [
            N("SYN-REC-001", "SYN-STABLE-001", "ae", "event_record", time_ref_ids=["SYN-TIME-001"],
              revision="SRC-REV-002", fields=fields_a),
            N("SYN-REC-002", "SYN-STABLE-001" if stable_equal else "SYN-STABLE-002", "ae", "event_record",
              time_ref_ids=["SYN-TIME-002"], revision=rev_b, fields=fields_b, **node_b),
        ]
        if unknown or dedup_mismatch:
            results = {"op_stable_identity": "unknown"}
            final = "ambiguous"
        else:
            results = {"op_stable_identity": "equal" if stable_equal else "different"}
            final = "matched" if stable_equal else "distinct"
        dup = None
        if mirror:
            dup = DP("SYN-DUP-001", mirror=True, collision=collision)
        elif modeling:
            dup = DP("SYN-DUP-001", mirror=False, collision=collision)
        elif dedup_mismatch:
            dup = DP("SYN-DUP-001", mirror=False, collision=collision, keys=["non_observed_field"])
        elif collision != "independent_events":
            dup = DP("SYN-DUP-001", mirror=False, collision=collision)
        spec: dict[str, Any] = {
            "family": "identity_duplicate_matrix", "token": "d08_identity_collision",
            "disposition": disp, "grain": "per_left_anchor_slot",
            "mutation": {"class": mc, "desc": desc},
            "times": times, "nodes": nodes,
            "rules": [_rule("SYN-RULE-IDM-001", relationship_type="identity_duplicate",
                            anchor_role="left", evidence_role="right", grain="per_left_anchor_slot",
                            cardinality_ref="SYN-CARD-001", directionality="undirected",
                            producer_domains=["D01"], owner_domain="D08",
                            authority_locator="SYN-AUTH-001",
                            left_constraint="identity_evidence_a", right_constraint="identity_evidence_b")],
            "cards": [_cardinality("SYN-CARD-001", left_min=1, left_max=1, right_min=1, right_max=1,
                                   unmatched="positive_missing_required", overmatch="allowed",
                                   bidirectional=False, reverse_required=False)],
            "identity_cmp": [IC("SYN-IC-001", "SYN-RULE-IDM-001", results=results, final=final,
                                reason=[desc])],
            "coverage": [CV("D01")],
            "route": {"required_producer_domains": ["D01"]},
        }
        if dup is not None:
            spec["dup"] = [dup]
        if subject_b:
            spec["spine"] = {"scope_equality_decision": False, "shared_spine_ref": "SYN-SPINE-001"}
        specs.append(spec)
    return specs


