def build_correction_matrix_specs() -> list[dict[str, Any]]:
    specs: list[dict[str, Any]] = []
    for idx, (disp, mc, desc, source_rev, declared, actual, changed, consumed, cause,
              dtype, derived_consumed, node_rev, fingerprint) in enumerate(MPROP_ROWS, start=1):
        times = [T("SYN-TIME-001", "2026-01-10")]
        dconsumed = derived_consumed if derived_consumed is not None else declared
        node = N("SYN-REC-001", "SYN-STABLE-001", "cm", "treatment_record", time_ref_ids=["SYN-TIME-001"],
                 revision=node_rev if node_rev is not None else source_rev,
                 fields={"dose_amount": 10, "grade_code": "G1", "result_value": 3})
        derived_id = f"SYN-DERIVED-M{idx:03d}"
        specs.append({
            "family": "correction_propagation_matrix", "token": "d08_propagation_lineage",
            "disposition": disp, "grain": "per_propagation_derived_object",
            "mutation": {"class": mc, "desc": desc},
            "times": times, "nodes": [node],
            "rules": [_rule("SYN-RULE-PROPM-001", relationship_type="modification_propagation_matrix",
                            anchor_role="left", evidence_role="right", grain="per_propagation_derived_object",
                            cardinality_ref="SYN-CARD-001", directionality="directed",
                            producer_domains=["D06"], owner_domain="D08",
                            authority_locator="SYN-AUTH-001",
                            left_constraint="source_record", right_constraint="derived_object")],
            "cards": [_cardinality("SYN-CARD-001", left_min=1, left_max=1, right_min=1, right_max=1,
                                   unmatched="not_applicable", overmatch="allowed",
                                   bidirectional=False, reverse_required=False,
                                   grain="per_propagation_derived_object")],
            "derived": [DV(derived_id, dtype, consumed=dconsumed)],
            "props": [PR(f"SYN-PROP-M{idx:03d}", "SYN-REC-001", source_rev=source_rev, cause=cause,
                         changed=changed, derived_id=derived_id, declared=declared, actual=actual,
                         intersection=list(set(changed) & set(consumed))
                         if cause not in ("rule_or_mapping", "algorithm") else [],
                         fingerprint=fingerprint)],
            "coverage": [CV("D06")],
            "bindings": [BD("SYN-BIND-001", "SYN-PROD-001", purpose="derive", outputs=["derived_value"])],
            "route": {"required_producer_domains": ["D06"]},
        })
    return specs


