def build_query_journey_specs() -> list[dict[str, Any]]:
    specs: list[dict[str, Any]] = []
    for (disp, mc, desc, blinded, projectable, anchor, extra) in QJ_ROWS:
        times = [T("SYN-TIME-001", "2026-01-10"), T("SYN-TIME-002", "2026-01-12")]
        subject_b = SUBJECT_REF_2 if extra.get("cross_scope") else SUBJECT_REF
        if extra.get("identity"):
            nodes = [N("SYN-REC-001", "SYN-STABLE-001", "ae", "event_record", time_ref_ids=["SYN-TIME-001"]),
                     N("SYN-REC-002", "SYN-STABLE-001", "ae", "event_record", time_ref_ids=["SYN-TIME-002"],
                       subject=SUBJECT_REF_2)]
            rule = _rule("SYN-RULE-QJ-001", relationship_type="identity_collision", anchor_role="left",
                         evidence_role="right", grain="per_left_anchor_slot", cardinality_ref="SYN-CARD-001",
                         directionality="undirected", producer_domains=["D01"], owner_domain="D08",
                         authority_locator="SYN-AUTH-001")
            idcmp = [IC("SYN-IC-001", "SYN-RULE-QJ-001", results={"op_stable_identity": "equal"},
                        final="matched")]
            route_domains = ["D01"]
            spine = {"scope_equality_decision": False, "shared_spine_ref": "SYN-SPINE-001"}
        else:
            nodes = [N("SYN-REC-001", "SYN-STABLE-001", "cm", "treatment_record", time_ref_ids=["SYN-TIME-001"]),
                     N("SYN-REC-002", "SYN-STABLE-002", "ae", "event_record", time_ref_ids=["SYN-TIME-002"],
                       subject=subject_b)]
            rule = _rule("SYN-RULE-QJ-001", relationship_type="explicit_link", anchor_role="left",
                         evidence_role="right", grain="per_left_anchor_slot", cardinality_ref="SYN-CARD-001",
                         directionality="directed", producer_domains=["D02", "D01"], owner_domain="D08",
                         authority_locator="SYN-AUTH-001")
            idcmp = []
            route_domains = ["D02", "D01"]
            spine = None
        jumps = []
        if extra.get("jumps"):
            jumps = [JP("SYN-JUMP-001", "record_node", "SYN-REC-002"),
                     JP("SYN-JUMP-002", "source_locator", "SYN-LOC-001")]
        if extra.get("jump_missing"):
            jumps = [JP("SYN-JUMP-001", "record_node", "SYN-REC-MISSING-999")]
        edges = []
        if not extra.get("identity") and not extra.get("wrong_subject"):
            if extra.get("cross_scope") or extra.get("fwd_only") or extra.get("no_phantom"):
                edges = [E("SYN-EDGE-001", "SYN-RULE-QJ-001", "SYN-STABLE-001", "SYN-STABLE-002",
                           rel_instance="REL-001")]
            else:
                edges = [E("SYN-EDGE-001", "SYN-RULE-QJ-001", "SYN-STABLE-001", "SYN-STABLE-002",
                           rel_instance="REL-001"),
                         E("SYN-EDGE-002", "SYN-RULE-QJ-001", "SYN-STABLE-002", "SYN-STABLE-001",
                           direction="reverse", rel_instance="REL-001")]
        joins = []
        if edges:
            if extra.get("cross_scope") or extra.get("fwd_only") or extra.get("no_phantom"):
                joins = [J("SYN-JOIN-001", "SYN-RULE-QJ-001", fwd_edges=["SYN-EDGE-001"], rev_edges=[],
                           fwd_ids=["SYN-STABLE-002"], rev_ids=[])]
            else:
                joins = [J("SYN-JOIN-001", "SYN-RULE-QJ-001", fwd_edges=["SYN-EDGE-001"],
                           rev_edges=["SYN-EDGE-002"], fwd_ids=["SYN-STABLE-002"], rev_ids=["SYN-STABLE-001"])]
        waivers = []
        if disp == "positive" and not extra.get("identity"):
            waivers = [WV("SYN-WAIVER-001", "SYN-RULE-QJ-001", "SYN-STABLE-001",
                          state="explicit_empty", owner="D02")]
        lexicon = None
        if extra.get("lexicon"):
            lexicon = dict(DEFAULT_LEXICON)
            lexicon["forbidden_internal_tokens"] = ["internal_relationship_token", "candidate_signal", "graph_node"]
        spec: dict[str, Any] = {
            "family": "query_journey_audience", "token": "d08_explicit_link_resolve",
            "disposition": disp, "grain": "per_left_anchor_slot",
            "mutation": {"class": mc, "desc": desc},
            "times": times, "nodes": nodes,
            "rules": [rule],
            "cards": [_cardinality("SYN-CARD-001", left_min=1, left_max=1, right_min=0, right_max=1,
                                   unmatched="positive_missing_required", overmatch="allowed",
                                   bidirectional=True, reverse_required=True)],
            "edges": edges, "joins": joins,
            "identity_cmp": idcmp,
            "coverage": [CV(dom) for dom in route_domains],
            "waivers": waivers,
            "vis": {"audience_anchor_rule": anchor, "audience_lexicon_ref": "SYN-LEX-001",
                    "blinded_node_ids": blinded, "evaluation_node_set": ["SYN-REC-001", "SYN-REC-002"],
                    "forbidden_node_ids": extra.get("forbidden", []), "projectable_node_set": projectable,
                    "visibility_decision_id": "SYN-VIS-001"},
            "jumps": jumps,
            "route": {"required_producer_domains": route_domains},
        }
        if lexicon is not None:
            spec["lexicon"] = lexicon
        if spine is not None:
            spec["spine"] = spine
        specs.append(spec)
    return specs


