# ---------------------------------------------------------------------------
# F17 anti-overfit (218-229): deterministic surface mutation of base fixtures
# ---------------------------------------------------------------------------
ANTI_OVERFIT_BASES = [
    # (case_number, base_index, mode)
    (218, 2, "strip_only"),
    (219, 13, "surface"),
    (220, 38, "surface"),
    (221, 49, "surface"),
    (222, 100, "surface"),
    (223, 14, "strip_only"),
    (224, 46, "surface"),
    (225, 80, "surface"),
    (226, 203, "strip_only"),
    (227, 182, "surface"),
    (228, 59, "surface"),
    (229, 200, "surface"),
]


def build_anti_overfit_rows(base_rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for case_number, base_index, mode in ANTI_OVERFIT_BASES:
        base = base_rows[base_index - 1]
        base_typed = base["typed_input"]
        mutated = mutate_surface(base_typed, mode, case_number)
        apply_field_rename = mode == "surface" and not mutated.get("propagation_objects")
        if not apply_field_rename and mode == "surface":
            # propagation bases: field keys are consumed-field operands; keep them stable
            pass
        changes: list[dict[str, str]] = []
        if mode == "strip_only":
            changes = [
                {"changed_token": "run_ref", "from_value": RUN_REF, "to_value": f"SYN-D08-RUN-OVF-{case_number}"},
                {"changed_token": "accepted_snapshot_ref", "from_value": SNAPSHOT_REF, "to_value": f"SYN-D08-SNAP-OVF-{case_number}"},
                {"changed_token": "producer_version", "from_value": "SYN-PV-001", "to_value": f"SYN-PV-OVF-{case_number}"},
                {"changed_token": "authority_version", "from_value": "SYN-AV-001", "to_value": f"SYN-AV-OVF-{case_number}"},
                {"changed_token": "snapshot_as_of", "from_value": SNAPSHOT_AS_OF, "to_value": "2026-07-02T00:00:00+00:00"},
            ]
        else:
            changes = [
                {"changed_token": "project_ref", "from_value": PROJECT_REF, "to_value": f"SYN-D08-PROJECT-OVF-{case_number}"},
                {"changed_token": "source_table_label", "from_value": "SYN-TBL-A", "to_value": f"SYN-TBL-OVF-{case_number}"},
                {"changed_token": "source_file_ref", "from_value": _SOURCE_FILE, "to_value": f"synthetic_source/dataset_ovf_{case_number}.json"},
                {"changed_token": "locator_kind", "from_value": _LOCATOR_KIND, "to_value": f"synthetic_file_ovf_{case_number}"},
                {"changed_token": "list_order", "from_value": "canonical order", "to_value": "reversed record_nodes/time_refs/source_locators/observed_edges"},
                {"changed_token": "run_ref", "from_value": RUN_REF, "to_value": f"SYN-D08-RUN-OVF-{case_number}"},
                {"changed_token": "producer_version", "from_value": "SYN-PV-001", "to_value": f"SYN-PV-OVF-{case_number}"},
            ]
            if apply_field_rename:
                changes.insert(4, {"changed_token": "field_keys",
                                   "from_value": "accepted_source_field_values keys",
                                   "to_value": "renamed with _syn suffix"})
        mutated["mutation_context"]["mutation_class"] = "anti_overfit_surface"
        mutated["mutation_context"]["mutation_description"] = (
            f"anti-overfit ({mode}): surface-only mutation of {base['case_id']}; "
            f"same substantive relation semantic and disposition {base['disposition']}")
        mutated["mutation_context"]["base_fixture_id"] = base["fixture_id"]
        mutated["mutation_context"]["variant_of"] = base["case_id"]
        mutated["anti_overfit_variant"] = {
            "base_fixture_id": base["fixture_id"],
            "semantic_equivalence_ref": base["case_id"],
            "surface_changes": changes,
            "variant_id": f"D08-OVF-{case_number:03d}",
        }
        mutated["mutation_context"]["substantive_input_hash"] = substantive_input_hash(mutated)
        spec = {
            "family": "anti_overfit",
            "token": base["clinical_claim_token"],
            "disposition": base["disposition"],
            "grain": base["grain"],
            "mutation": {"class": "anti_overfit_surface",
                         "desc": f"anti-overfit variant of {base['case_id']} ({mode})"},
            "route": dict(base["owner_route"]),
        }
        rows.append(build_case_row(mutated, spec, case_number))
    return rows


# ---------------------------------------------------------------------------
# Waiver tri-state cases (230-232): closure_state full_set / missing must be
# materialized (explicit_empty already covered); acceptance record pin.
# ---------------------------------------------------------------------------
def build_waiver_state_specs() -> list[dict[str, Any]]:
    specs: list[dict[str, Any]] = []
    # 230: full_set closure, all authorized objects resolve, link conserved -> negative
    times = [T("SYN-TIME-001", "2026-01-10"), T("SYN-TIME-002", "2026-01-12")]
    specs.append({
        "family": "special_floors", "token": "d08_explicit_link_resolve",
        "disposition": "negative", "grain": "per_left_anchor_slot",
        "mutation": {"class": "waiver_state",
                     "desc": "waiver closure_state=full_set: handoff lists all authorized objects; link resolves and is conserved -> negative"},
        "times": times,
        "nodes": [N("SYN-REC-001", "SYN-STABLE-001", "cm", "treatment_record", time_ref_ids=["SYN-TIME-001"]),
                  N("SYN-REC-002", "SYN-STABLE-002", "ae", "event_record", time_ref_ids=["SYN-TIME-002"])],
        "rules": [_link_rule()], "cards": [_link_card()],
        "raw": [RAW("SYN-RAWLINK-001", domain="cm", idvarval="SYN-REC-001", relid="REL-001"),
                RAW("SYN-RAWLINK-002", domain="ae", idvarval="SYN-REC-002", relid="REL-001")],
        "resolves": [RES("SYN-RES-001", "SYN-RAWLINK-001", status="unique", materialized=["SYN-REC-001"]),
                     RES("SYN-RES-002", "SYN-RAWLINK-002", status="unique", materialized=["SYN-REC-002"])],
        "edges": [E("SYN-EDGE-001", "SYN-RULE-LINK-001", "SYN-STABLE-001", "SYN-STABLE-002", rel_instance="REL-001"),
                  E("SYN-EDGE-002", "SYN-RULE-LINK-001", "SYN-STABLE-002", "SYN-STABLE-001", direction="reverse", rel_instance="REL-001")],
        "joins": [J("SYN-JOIN-001", "SYN-RULE-LINK-001", fwd_edges=["SYN-EDGE-001"], rev_edges=["SYN-EDGE-002"],
                    fwd_ids=["SYN-STABLE-002"], rev_ids=["SYN-STABLE-001"])],
        "coverage": [CV("D02"), CV("D01")],
        "waivers": [WV("SYN-WAIVER-001", "SYN-RULE-LINK-001", "SYN-STABLE-001",
                       state="full_set", owner="D02",
                       refs=["SYN-STABLE-002"])],
        "route": {"required_producer_domains": ["D02", "D01"]},
    })
    # 231: closure_state=missing -> not_evaluable; must NOT assume 'no waiver'
    times = [T("SYN-TIME-001", "2026-01-10")]
    specs.append({
        "family": "special_floors", "token": "d08_explicit_link_resolve",
        "disposition": "not_evaluable", "grain": "per_left_anchor_slot",
        "mutation": {"class": "waiver_state",
                     "desc": "waiver closure_state=missing: D08 unit is not_evaluable; MUST NOT assume 'no waiver' or emit positive not-found"},
        "times": times,
        "nodes": [N("SYN-REC-001", "SYN-STABLE-001", "cm", "treatment_record", time_ref_ids=["SYN-TIME-001"])],
        "rules": [_link_rule()], "cards": [_link_card()],
        "raw": [RAW("SYN-RAWLINK-001", domain="cm", idvarval="SYN-REC-001", relid="REL-001")],
        "resolves": [RES("SYN-RES-001", "SYN-RAWLINK-001", status="not_found", materialized=[])],
        "coverage": [CV("D02"), CV("D01")],
        "waivers": [WV("SYN-WAIVER-001", "SYN-RULE-LINK-001", "SYN-STABLE-001",
                       state="missing", owner="D02")],
        "route": {"required_producer_domains": ["D02", "D01"]},
    })
    # 232: full_set closure but one authorized object unresolvable -> not_evaluable
    times = [T("SYN-TIME-001", "2026-01-10"), T("SYN-TIME-002", "2026-01-12")]
    specs.append({
        "family": "special_floors", "token": "d08_explicit_link_resolve",
        "disposition": "not_evaluable", "grain": "per_left_anchor_slot",
        "mutation": {"class": "waiver_state",
                     "desc": "waiver closure_state=full_set but an authorized object cannot be located -> not_evaluable (closure not provable)"},
        "times": times,
        "nodes": [N("SYN-REC-001", "SYN-STABLE-001", "cm", "treatment_record", time_ref_ids=["SYN-TIME-001"]),
                  N("SYN-REC-002", "SYN-STABLE-002", "ae", "event_record", time_ref_ids=["SYN-TIME-002"])],
        "rules": [_link_rule()], "cards": [_link_card()],
        "raw": [RAW("SYN-RAWLINK-001", domain="cm", idvarval="SYN-REC-001", relid="REL-001")],
        "resolves": [RES("SYN-RES-001", "SYN-RAWLINK-001", status="unique", materialized=["SYN-REC-001"])],
        "edges": [E("SYN-EDGE-001", "SYN-RULE-LINK-001", "SYN-STABLE-001", "SYN-STABLE-002", rel_instance="REL-001")],
        "joins": [J("SYN-JOIN-001", "SYN-RULE-LINK-001", fwd_edges=["SYN-EDGE-001"], rev_edges=[],
                    fwd_ids=["SYN-STABLE-002"], rev_ids=[])],
        "coverage": [CV("D02"), CV("D01")],
        "waivers": [WV("SYN-WAIVER-001", "SYN-RULE-LINK-001", "SYN-STABLE-001",
                       state="full_set", owner="D02",
                       refs=["SYN-STABLE-MISSING-999"])],
        "route": {"required_producer_domains": ["D02", "D01"]},
    })
    return specs


# ---------------------------------------------------------------------------
# Cutoff negative-case extra (233): time-missing + all other members
# out-of-cutoff -> exactly one not_evaluable unit (acceptance record next step:
# the all-out-of-cutoff zero-units rule must NOT swallow time-missing priority).
# ---------------------------------------------------------------------------
def build_cutoff_time_missing_all_out_spec() -> list[dict[str, Any]]:
    times = [T("SYN-TIME-001", "", precision="day", kind="point", tz_state="missing"),
             T("SYN-TIME-002", "2026-08-01", precision="day", kind="point"),
             T("SYN-TIME-003", "2026-08-02", precision="day", kind="point")]
    return [{
        "family": "cutoff_matrix", "token": "d08_explicit_link_resolve",
        "disposition": "not_evaluable", "grain": "per_left_anchor_slot",
        "mutation": {"class": "cutoff_oracle",
                     "desc": "cutoff negative-case: time-missing member coexists with ALL other members out-of-cutoff -> exactly one not_evaluable unit; all-out-of-cutoff zero-units rule must NOT swallow the time-missing priority"},
        "times": times,
        "nodes": [N("SYN-REC-001", "SYN-STABLE-001", "cm", "treatment_record", time_ref_ids=["SYN-TIME-001"],
                    cutoff="time_missing_not_evaluable"),
                  N("SYN-REC-002", "SYN-STABLE-002", "ae", "event_record", time_ref_ids=["SYN-TIME-002"],
                    cutoff="out_of_cutoff"),
                  N("SYN-REC-003", "SYN-STABLE-003", "ae", "event_record", time_ref_ids=["SYN-TIME-003"],
                    cutoff="out_of_cutoff")],
        "rules": [_link_rule()], "cards": [_link_card()],
        "raw": [RAW("SYN-RAWLINK-001", domain="cm", idvarval="SYN-REC-001", relid="REL-001")],
        "resolves": [RES("SYN-RES-001", "SYN-RAWLINK-001", status="not_evaluable", l0="covered")],
        "coverage": [CV("D02"), CV("D01")],
        "route": {"required_producer_domains": ["D02", "D01"]},
    }]


# ---------------------------------------------------------------------------
# Catalog assembly
# ---------------------------------------------------------------------------
def all_specs() -> list[dict[str, Any]]:
    specs: list[dict[str, Any]] = list(CORE_SPECS)
    specs.extend(build_consume_only_specs())
    specs.extend(build_temporal_matrix_specs())
    specs.extend(build_identity_matrix_specs())
    specs.extend(build_correction_matrix_specs())
    specs.extend(build_query_journey_specs())
    specs.extend(build_integrity_specs())
    specs.extend(build_raw_materialized_specs())
    specs.extend(build_replay_specs())
    specs.extend(build_fanout_specs())
    specs.extend(build_cutoff_specs())
    specs.extend(build_special_specs())
    return specs


def assemble_catalog() -> dict[str, Any]:
    specs = all_specs()
    cases: list[dict[str, Any]] = []
    for idx, spec in enumerate(specs, start=1):
        typed = build_typed_input(spec)
        cases.append(build_case_row(typed, spec, idx))
    cases.extend(build_anti_overfit_rows(cases))
    waiver_specs = build_waiver_state_specs()
    for idx, spec in enumerate(waiver_specs, start=len(cases) + 1):
        cases.append(build_case_row(build_typed_input(spec), spec, idx))
    cutoff_extra = build_cutoff_time_missing_all_out_spec()
    for idx, spec in enumerate(cutoff_extra, start=len(cases) + 1):
        cases.append(build_case_row(build_typed_input(spec), spec, idx))
    catalog = {
        "catalog_id": CATALOG_ID,
        "version": SCHEMA_VERSION,
        "case_count": len(cases),
        "catalog_hash": None,
        "cases": cases,
    }
    catalog["catalog_hash"] = content_hash(catalog, "catalog_hash")
    return catalog




