SECTION_ITEM_KEYS: dict[str, list[str]] = {
    "record_nodes": RECORD_NODE_KEYS,
    "relation_rules": RELATION_RULE_KEYS,
    "cardinality_specs": CARDINALITY_SPEC_KEYS,
    "raw_links": RAW_LINK_KEYS,
    "resolve_decisions": RESOLVE_DECISION_KEYS,
    "rel_instance_memberships": REL_INSTANCE_MEMBERSHIP_KEYS,
    "observed_edges": OBSERVED_EDGE_KEYS,
    "bidirectional_joins": BIDIRECTIONAL_JOIN_KEYS,
    "temporal_comparisons": TEMPORAL_COMPARISON_KEYS,
    "identity_comparisons": IDENTITY_COMPARISON_KEYS,
    "time_refs": TIME_REF_KEYS,
    "identity_operands": IDENTITY_OPERAND_KEYS,
    "coverage_status": COVERAGE_STATUS_KEYS,
    "waiver_handoffs": WAIVER_HANDOFF_KEYS,
    "propagation_objects": PROPAGATION_OBJECT_KEYS,
    "derived_objects": DERIVED_OBJECT_KEYS,
    "duplicate_policies": DUPLICATE_POLICY_KEYS,
    "fanout_candidate_sets": FANOUT_CANDIDATE_SET_KEYS,
    "producer_consumption_bindings": PRODUCER_CONSUMPTION_BINDING_KEYS,
    "authority_bindings": AUTHORITY_BINDING_KEYS,
    "source_locators": SOURCE_LOCATOR_KEYS,
    "visit_refs": VISIT_REF_KEYS,
    "source_jump_registry": SOURCE_JUMP_TARGET_KEYS,
}

CARDINALITY_REVERSE_REQUIRED_ALLOWED = ("per_left_anchor_slot", "per_explicit_rel_instance")


def validate_typed_input(typed: dict[str, Any], case_id: str, family: str = "") -> None:
    expect_exact_keys(typed, TYPED_INPUT_SECTION_KEYS, f"{case_id} typed_input envelope")
    if typed["input_schema"] != TYPED_INPUT_SCHEMA:
        raise D08ArtifactError("schema_parse", "schema_error",
                               f"{case_id} input_schema != {TYPED_INPUT_SCHEMA}")
    for key in TYPED_INPUT_LIST_SECTIONS:
        if not isinstance(typed[key], list):
            raise D08ArtifactError("schema_parse", "schema_error", f"{case_id} typed_input.{key} is not a list")
    for key in TYPED_INPUT_DICT_SECTIONS:
        if not isinstance(typed[key], dict):
            raise D08ArtifactError("schema_parse", "schema_error", f"{case_id} typed_input.{key} is not an object")
    for key in TYPED_INPUT_NULLABLE_DICT_SECTIONS:
        if typed[key] is not None and not isinstance(typed[key], dict):
            raise D08ArtifactError("schema_parse", "schema_error",
                                   f"{case_id} typed_input.{key} must be null or an object")
    scope = typed["scope_binding"]
    expect_exact_keys(scope, SCOPE_BINDING_KEYS, f"{case_id} scope_binding")
    for field in ("project_ref", "run_ref", "subject_ref", "site_ref", "scope_binding_id", "episode_key"):
        require_string(scope[field], f"{case_id} scope_binding.{field}")
    if not scope["project_ref"].startswith("SYN-D08-"):
        raise D08ArtifactError("schema_parse", "schema_error",
                               f"{case_id} project_ref must be synthetic SYN-D08-*")
    if not re.fullmatch(r"[0-9a-f]{64}", scope["lineage_hash"]):
        raise D08ArtifactError("schema_parse", "schema_error",
                               f"{case_id} scope_binding.lineage_hash must be sha256 hex")
    mc = typed["mutation_context"]
    expect_exact_keys(mc, MUTATION_CONTEXT_KEYS, f"{case_id} mutation_context")
    require_enum(mc["mutation_class"], MUTATION_CLASSES, f"{case_id} mutation_class")
    expect_exact_keys(typed["visibility_decision"], VISIBILITY_DECISION_KEYS, f"{case_id} visibility_decision")
    _vis = typed["visibility_decision"]
    if set(_vis["projectable_node_set"]) & (set(_vis["blinded_node_ids"]) | set(_vis["forbidden_node_ids"])):
        raise D08ArtifactError("hidden_leakage", "leak_detected",
                               f"{case_id} projectable set leaks a blinded/forbidden node")
    if not set(_vis["projectable_node_set"]).issubset(set(_vis["evaluation_node_set"])):
        raise D08ArtifactError("hidden_leakage", "projectable_scope",
                               f"{case_id} projectable set not subset of evaluation set")
    expect_exact_keys(typed["audience_lexicon"], AUDIENCE_LEXICON_KEYS, f"{case_id} audience_lexicon")
    if typed["anti_overfit_variant"] is not None:
        expect_exact_keys(typed["anti_overfit_variant"], ANTI_OVERFIT_VARIANT_KEYS,
                          f"{case_id} anti_overfit_variant")
        for change in typed["anti_overfit_variant"]["surface_changes"]:
            expect_exact_keys(change, SURFACE_CHANGE_KEYS, f"{case_id} surface_change")
    if typed["shared_spine_binding"] is not None:
        expect_exact_keys(typed["shared_spine_binding"], SHARED_SPINE_BINDING_KEYS,
                          f"{case_id} shared_spine_binding")
    for section, keys in SECTION_ITEM_KEYS.items():
        for item in typed[section]:
            expect_exact_keys(item, keys, f"{case_id} {section} item")
    for node in typed["record_nodes"]:
        expect_exact_keys(node["stable_record_identity"], STABLE_IDENTITY_KEYS,
                          f"{case_id} record_node.stable_record_identity")
        expect_exact_keys(node["cutoff_decision"], CUTOFF_DECISION_KEYS, f"{case_id} record_node.cutoff_decision")
        require_enum(node["record_status"], RECORD_STATUSES, f"{case_id} record_status")
        require_enum(node["cutoff_decision"]["decision"], CUTOFF_DECISIONS, f"{case_id} cutoff_decision")
        require_string(node["record_node_id"], f"{case_id} record_node_id")
        require_string(node["stable_record_identity"]["stable_record_id"], f"{case_id} stable_record_id")
    for rule in typed["relation_rules"]:
        expect_exact_keys(rule["applicability_window"], APPLICABILITY_WINDOW_KEYS,
                          f"{case_id} rule.applicability_window")
        require_enum(rule["unit_grain"], UNIT_GRAINS, f"{case_id} rule.unit_grain")
        require_enum(rule["owner_domain"], OWNER_DOMAINS, f"{case_id} rule.owner_domain")
        require_enum(rule["directionality"], ("directed", "bidirectional", "undirected"),
                     f"{case_id} rule.directionality")
        if rule["expected_relation"] is not None:
            require_enum(rule["expected_relation"], TEMPORAL_RESULTS, f"{case_id} rule.expected_relation")
        for token in ("required_relation", "forbidden_relation"):
            if rule[token] is not None:
                require_enum(rule[token], TEMPORAL_RESULTS, f"{case_id} rule.{token}")
    for card in typed["cardinality_specs"]:
        require_enum(card["unmatched_required_policy"], UNMATCHED_POLICIES,
                     f"{case_id} cardinality.unmatched_required_policy")
        require_enum(card["overmatch_policy"], OVERMATCH_POLICIES, f"{case_id} cardinality.overmatch_policy")
        require_enum(card["unit_grain"], UNIT_GRAINS, f"{case_id} cardinality.unit_grain")
        if card["left_min"] > card["left_max"] or card["right_min"] > card["right_max"]:
            if not (family == "integrity_coverage"):
                # only allowed for the intentional bad_card integrity fixture (173)
                raise D08ArtifactError("schema_parse", "schema_error",
                                       f"{case_id} cardinality min > max (invalid)")
    for res in typed["resolve_decisions"]:
        require_enum(res["status"], RESOLVE_STATUSES, f"{case_id} resolve.status")
        require_enum(res["l0_coverage_status"], L0_STATUSES, f"{case_id} resolve.l0_coverage_status")
    for cov in typed["coverage_status"]:
        require_enum(cov["l0_status"], L0_STATUSES, f"{case_id} coverage.l0_status")
        require_enum(cov["producer_domain"], OWNER_DOMAINS, f"{case_id} coverage.producer_domain")
    for w in typed["waiver_handoffs"]:
        require_enum(w["closure_state"], CLOSURE_STATES, f"{case_id} waiver.closure_state")
        if w["closure_state"] == "full_set" and not w["authorized_object_refs"]:
            raise D08ArtifactError("schema_parse", "schema_error",
                                   f"{case_id} waiver full_set must list authorized objects")
        if w["closure_state"] == "explicit_empty" and w["authorized_object_refs"]:
            raise D08ArtifactError("schema_parse", "schema_error",
                                   f"{case_id} waiver explicit_empty must have empty refs")
        if w["closure_state"] == "missing" and w["authorized_object_refs"]:
            raise D08ArtifactError("schema_parse", "schema_error",
                                   f"{case_id} waiver missing must not carry refs")
    for p in typed["propagation_objects"]:
        require_enum(p["change_cause"], CHANGE_CAUSES, f"{case_id} propagation.change_cause")
        require_enum(p["derived_object_type"], DERIVED_OBJECT_TYPES, f"{case_id} propagation.derived_object_type")
    for d in typed["derived_objects"]:
        require_enum(d["derived_object_type"], DERIVED_OBJECT_TYPES, f"{case_id} derived.derived_object_type")
    for t in typed["time_refs"]:
        require_enum(t["precision"], PRECISION_LEVELS, f"{case_id} time_ref.precision")
        require_enum(t["timezone_state"], TIMEZONE_STATES, f"{case_id} time_ref.timezone_state")
        require_enum(t["kind"], TIME_KINDS, f"{case_id} time_ref.kind")
        if t["timezone_state"] == "present" and not t["timezone"]:
            raise D08ArtifactError("schema_parse", "schema_error",
                                   f"{case_id} time_ref present timezone must be non-empty")
    for tc in typed["temporal_comparisons"]:
        if tc["timezone_state"] in ("missing", "incomparable"):
            pass
    for ic in typed["identity_comparisons"]:
        require_enum(ic["final_result"], ("matched", "distinct", "ambiguous"),
                     f"{case_id} identity_comparison.final_result")
    for fs in typed["fanout_candidate_sets"]:
        if fs["max_unidentified_fanout"] <= 0:
            raise D08ArtifactError("schema_parse", "schema_error", f"{case_id} fanout cap must be positive")


def validate_case(case: dict[str, Any], index: int) -> None:
    expect_exact_keys(case, CASE_KEYS, f"catalog case {index}")
    case_id = require_string(case["case_id"], "case_id")
    n = f"{index:03d}"
    if case_id != f"D08-CASE-{n}":
        raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                               f"{case_id} does not match sequential index {n}")
    if case["fixture_id"] != f"D08-FIXTURE-{n}":
        raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                               f"{case_id} fixture_id mismatch")
    if case["oracle_case_id"] != f"D08-ORACLE-{n}":
        raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                               f"{case_id} oracle_case_id mismatch")
    if case["manifest_case_id"] != f"D08-MANIFEST-{n}":
        raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                               f"{case_id} manifest_case_id mismatch")
    if case["clinical_claim_token"] not in CLINICAL_CLAIM_TOKENS:
        raise D08ArtifactError("schema_parse", "schema_error",
                               f"{case_id} clinical_claim_token not in closed enum")
    if case["disposition"] not in DISPOSITIONS + (CONSUME_ONLY_DISPOSITION,):
        raise D08ArtifactError("schema_parse", "schema_error", f"{case_id} disposition not in closed set")
    require_enum(case["grain"], UNIT_GRAINS, f"{case_id} grain")
    if case["family_id"] not in FAMILY_FLOORS:
        raise D08ArtifactError("schema_parse", "schema_error", f"{case_id} unknown family_id")
    require_enum(case["mutation_class"], MUTATION_CLASSES, f"{case_id} mutation_class")
    for leaf_key in ("expected_leaf_set", "expected_trace_leaf_set", "expected_source_leaf_set"):
        if case[leaf_key] is not None:
            raise D08ArtifactError(
                "schema_parse", "schema_error",
                f"{case_id} {leaf_key} must be null in the typed-input-only catalog (design D2)")
    expect_exact_keys(case["owner_route"], OWNER_ROUTE_KEYS, f"{case_id} owner_route")
    expect_exact_keys(case["audience_contract"], AUDIENCE_CONTRACT_KEYS, f"{case_id} audience_contract")
    if case["owner_route"]["owner_domain"] != "D08" and case["family_id"] != "consume_only_adjacency":
        raise D08ArtifactError("schema_parse", "schema_error",
                               f"{case_id} non-D08 owner_domain outside consume_only family")
    typed = case["typed_input"]
    validate_typed_input(typed, case_id, case["family_id"])
    expect_exact_keys(typed, TYPED_INPUT_SECTION_KEYS, f"{case_id} typed_input envelope")
    if case["fixture_hash"] != sha256_text(canonical_json(typed)):
        raise D08ArtifactError("canonical_hash", "stale_hash", f"{case_id} fixture_hash mismatch")
    if typed["mutation_context"]["substantive_input_hash"] != substantive_input_hash(typed):
        raise D08ArtifactError("canonical_hash", "stale_hash",
                               f"{case_id} substantive_input_hash mismatch")
    _validate_case_crossrefs(case, case_id)


def _validate_case_crossrefs(case: dict[str, Any], case_id: str) -> None:
    typed = case["typed_input"]
    node_ids = {n["record_node_id"] for n in typed["record_nodes"]}
    stable_ids = {n["stable_record_identity"]["stable_record_id"] for n in typed["record_nodes"]}
    time_ids = {t["time_ref_id"] for t in typed["time_refs"]}
    rule_ids = {r["rule_id"] for r in typed["relation_rules"]}
    raw_ids = {r["raw_link_id"] for r in typed["raw_links"]}
    derived_ids = {d["derived_object_id"] for d in typed["derived_objects"]}
    auth_ids = {a["authority_binding_id"] for a in typed["authority_bindings"]}
    loc_ids = {loc["source_locator_id"] for loc in typed["source_locators"]}
    family = case["family_id"]
    for ref in case["owner_route"]["rule_refs"]:
        if ref not in rule_ids:
            raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                   f"{case_id} owner_route.rule_refs {ref} unresolved")
    for ref in case["owner_route"]["locator_ids"]:
        if ref not in loc_ids:
            raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                   f"{case_id} owner_route.locator_ids {ref} unresolved")
    for rule in typed["relation_rules"]:
        if rule["authority_locator_id"] not in auth_ids and not (
                family == "integrity_coverage" and case["mutation_class"] == "integrity_gap"):
            raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                   f"{case_id} rule {rule['rule_id']} authority locator unresolved")
    for node in typed["record_nodes"]:
        for tid in node["time_ref_ids"]:
            if tid not in time_ids:
                raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                       f"{case_id} node {node['record_node_id']} time_ref {tid} unresolved")
    for tc in typed["temporal_comparisons"]:
        if tc["left_time_ref_id"] not in time_ids or tc["right_time_ref_id"] not in time_ids:
            raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                   f"{case_id} temporal comparison time refs unresolved")
    for mem in typed["rel_instance_memberships"]:
        if mem["relation_rule_id"] not in rule_ids:
            raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                   f"{case_id} membership rule unresolved")
        for member in mem["member_ids"]:
            if member not in stable_ids:
                raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                       f"{case_id} membership member {member} unresolved")
        for raw in mem["raw_link_ids"]:
            if raw not in raw_ids:
                raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                       f"{case_id} membership raw link {raw} unresolved")
    for edge in typed["observed_edges"]:
        if edge["relation_rule_id"] not in rule_ids:
            raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                   f"{case_id} edge rule unresolved")
        dangling_ok = (family == "fanout_gate" and case["mutation_class"] == "integrity_gap")
        if edge["left_stable_identity"] not in stable_ids and not dangling_ok:
            raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                   f"{case_id} edge left stable identity unresolved")
        if edge["right_stable_identity"] not in stable_ids:
            raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                   f"{case_id} edge right stable identity unresolved")
    for prop in typed["propagation_objects"]:
        if prop["derived_object_id"] not in derived_ids:
            raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                   f"{case_id} propagation derived object unresolved")
        if prop["source_record_node_id"] not in node_ids:
            raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                   f"{case_id} propagation source node unresolved")
    for w in typed["waiver_handoffs"]:
        if w["relation_rule_id"] not in rule_ids:
            raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                   f"{case_id} waiver rule unresolved")
        if w["anchor_stable_identity"] not in stable_ids:
            raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                   f"{case_id} waiver anchor unresolved")
    vis = typed["visibility_decision"]
    for member in vis["evaluation_node_set"] + vis["projectable_node_set"] + vis["blinded_node_ids"] + vis["forbidden_node_ids"]:
        if member not in node_ids:
            raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                   f"{case_id} visibility member {member} unresolved")
    for member in case["audience_contract"]["projectable_node_set"]:
        if member not in node_ids:
            raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                   f"{case_id} audience_contract member {member} unresolved")
    for res in typed["resolve_decisions"]:
        if res["raw_link_id"] not in raw_ids:
            raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                   f"{case_id} resolve raw link unresolved")
        unique_no_materialized = res["status"] == "unique" and not res["materialized_record_node_ids"]
        if unique_no_materialized and family not in ("integrity_coverage", "raw_materialized_bijection"):
            raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                   f"{case_id} resolve unique without materialized node")


def check_case_consistency(case: dict[str, Any]) -> None:
    """Schema-level owner-routing consistency only.

    The worker_01 consolidation removed the disposition-rule branches (coverage/
    waiver/timezone/cutoff/propagation) that worker_03's scaffold used to
    validate the design-intent labels: those are medical-expectation branches
    and now live in the independent verifier in tests/test_d08_artifact_generator.py.
    """
    disp = case["disposition"]
    family = case["family_id"]
    case_id = case["case_id"]
    if family == "consume_only_adjacency":
        if disp != CONSUME_ONLY_DISPOSITION:
            raise D08ArtifactError("consistency", "disposition_conflict",
                                   f"{case_id} consume_only requires disposition consume_only")
        if case["clinical_claim_token"] in D08_OWNED_TOKENS:
            raise D08ArtifactError("consistency", "owner_routing_conflict",
                                   f"{case_id} consume_only case uses an owned d08_* token")
        return
    if disp not in DISPOSITIONS:
        raise D08ArtifactError("consistency", "disposition_conflict",
                               f"{case_id} invalid disposition {disp}")
    if case["clinical_claim_token"] not in D08_OWNED_TOKENS | {"d08_routing_or_coverage_gate"}:
        raise D08ArtifactError("consistency", "owner_routing_conflict",
                               f"{case_id} non-d08 token must be consume_only")
    if disp == CONSUME_ONLY_DISPOSITION and family != "consume_only_adjacency":
        raise D08ArtifactError("consistency", "owner_routing_conflict",
                               f"{case_id} consume_only disposition outside consume_only family")


def validate_catalog(catalog: dict[str, Any]) -> tuple[list[dict[str, Any]], dict[str, dict[str, Any]]]:
    expect_exact_keys(catalog, CATALOG_KEYS, "catalog top-level")
    if catalog["catalog_id"] != CATALOG_ID:
        raise D08ArtifactError("schema_parse", "schema_error", "catalog_id mismatch")
    if catalog["version"] != SCHEMA_VERSION:
        raise D08ArtifactError("schema_parse", "schema_error", "catalog version mismatch")
    cases = catalog["cases"]
    if not isinstance(cases, list) or len(cases) != catalog["case_count"] or len(cases) < MIN_CASE_COUNT:
        raise D08ArtifactError("identity/duplicate", "duplicate_identity",
                               f"catalog must contain >= {MIN_CASE_COUNT} cases (got {len(cases) if isinstance(cases, list) else 'n/a'})")
    if catalog["catalog_hash"] != content_hash(catalog, "catalog_hash"):
        raise D08ArtifactError("canonical_hash", "stale_hash", "catalog_hash mismatch")
    for index, case in enumerate(cases, start=1):
        validate_case(case, index)
        check_case_consistency(case)
    fixture_ids = [case["fixture_id"] for case in cases]
    if len(set(fixture_ids)) != len(cases):
        raise D08ArtifactError("identity/duplicate", "duplicate_identity", "fixture ids must be unique")
    by_id = {case["case_id"]: case for case in cases}
    return cases, by_id


# ---------------------------------------------------------------------------
# Distribution and duplicate-substantive-input checks (catalog-only)
# ---------------------------------------------------------------------------
def distribution_check(cases: list[dict[str, Any]]) -> dict[str, int]:
    from collections import Counter
    counts = Counter(case["family_id"] for case in cases)
    problems = []
    for family, floor in sorted(FAMILY_FLOORS.items()):
        if counts[family] < floor:
            problems.append(f"{family}: {counts[family]} < floor {floor}")
    if problems:
        raise D08ArtifactError("distribution", "floor_missed", "; ".join(problems))
    by_id = {case["case_id"]: case for case in cases}

    def require(cond: bool, msg: str) -> None:
        if not cond:
            raise D08ArtifactError("distribution", "floor_missed", msg)

    # Five D08-owned classes: five dispositions + counterevidence + hidden + FP + FN
    owned_families = [f for f in FAMILY_FLOORS if f.startswith("d08_")]
    for fam in owned_families:
        fam_cases = [c for c in cases if c["family_id"] == fam]
        disps = {c["disposition"] for c in fam_cases}
        for d in DISPOSITIONS:
            require(d in disps, f"{fam} missing disposition {d}")
        for mc in ("counterevidence", "hidden", "fp_trap", "fn_trap"):
            require(any(c["mutation_class"] == mc for c in fam_cases), f"{fam} missing {mc}")
    # Consume-only zero-risk
    co = [c for c in cases if c["family_id"] == "consume_only_adjacency"]
    require(len(co) >= 14, "consume_only < 14")
    require(all(c["disposition"] == CONSUME_ONLY_DISPOSITION for c in co), "consume_only disposition")
    require(all(c["clinical_claim_token"] not in D08_OWNED_TOKENS for c in co), "consume_only uses owned token")
    # Cutoff essentials (case ids fixed)
    cutoff_essentials = {
        "D08-CASE-200": ("negative", "all out-of-cutoff -> zero medical units"),
        "D08-CASE-201": ("boundary", "mixed membership -> exactly one cutoff_boundary_gate"),
        "D08-CASE-202": ("boundary", "single node spans-cutoff -> same boundary gate"),
        "D08-CASE-203": ("positive", "in-cutoff/covered/zero-match -> not-found path retained"),
        "D08-CASE-204": ("not_evaluable", "time-missing + mixed -> exactly one not_evaluable, no boundary gate"),
        "D08-CASE-205": ("positive", "in-cutoff -> out-of-cutoff correction retains propagation unit"),
        "D08-CASE-206": ("negative", "in-cutoff event, source revision after cutoff -> propagation check runs"),
        "D08-CASE-207": ("negative", "internal blinded join conserved but audience omitted"),
        "D08-CASE-233": ("not_evaluable", "time-missing + all other members out-of-cutoff -> exactly one not_evaluable, no gate, no zero-units swallow"),
    }
    for cid, (disp, note) in cutoff_essentials.items():
        case = by_id[cid]
        require(case["disposition"] == disp, f"{cid} cutoff essential mismatch: {note}")
    # Temporal oracle essentials
    temporal_essentials = {
        "D08-CASE-046": "positive",  # expected contains x observed contained_by -> positive
        "D08-CASE-047": "negative",  # explicit bidirectional allowed set
        "D08-CASE-090": "positive",  # overlap does not satisfy containment
        "D08-CASE-048": "not_evaluable",  # timezone + precision missing -> timezone_incomparable primary
    }
    for cid, disp in temporal_essentials.items():
        require(by_id[cid]["disposition"] == disp, f"{cid} temporal oracle essential mismatch")
    # Special floors (>=2 each)
    special = {
        "covered_zero_not_found": ["D08-CASE-208", "D08-CASE-209"],
        "uncovered_not_evaluable": ["D08-CASE-210", "D08-CASE-211"],
        "nary_relid_single_unit": ["D08-CASE-212", "D08-CASE-213", "D08-CASE-011", "D08-CASE-012"],
        "hidden_obligation": ["D08-CASE-007", "D08-CASE-145", "D08-CASE-214"],
        "date_revision_public_classifier": ["D08-CASE-215", "D08-CASE-216"],
        "rule_change_superseded": ["D08-CASE-056", "D08-CASE-217", "D08-CASE-123", "D08-CASE-124"],
    }
    for name, ids in special.items():
        require(all(cid in by_id for cid in ids), f"special floor {name} missing case ids")
    # Anti-overfit >= 12
    ao = [c for c in cases if c["family_id"] == "anti_overfit"]
    require(len(ao) >= 12, "anti_overfit < 12")
    for c in ao:
        require(c["mutation_class"] == "anti_overfit_surface", f"{c['case_id']} anti-overfit mutation class")
        require(c["typed_input"]["anti_overfit_variant"] is not None, f"{c['case_id']} missing anti_overfit_variant")
    # Waiver tri-state coverage: all three closure states appear somewhere
    states = {w["closure_state"] for c in cases for w in c["typed_input"]["waiver_handoffs"]}
    require(states == set(CLOSURE_STATES), f"waiver closure states must cover {CLOSURE_STATES}, got {sorted(states)}")
    return dict(counts)


def duplicate_substantive_check(cases: list[dict[str, Any]]) -> dict[str, list[str]]:
    by_id = {case["case_id"]: case for case in cases}
    groups: dict[str, list[str]] = {}
    for case in cases:
        h = case["typed_input"]["mutation_context"]["substantive_input_hash"]
        groups.setdefault(h, []).append(case["case_id"])
    problems: list[str] = []
    multi: dict[str, list[str]] = {}
    for h, ids in groups.items():
        if len(ids) < 2:
            continue
        multi[h] = ids
        disps = {by_id[i]["disposition"] for i in ids}
        if len(disps) > 1:
            problems.append(f"substantive group {ids} maps to conflicting dispositions {sorted(disps)}")
    if problems:
        raise D08ArtifactError("substantive_input", "duplicate_conflict", "; ".join(problems))
    return multi



