# ---------------------------------------------------------------------------
# (The worker_03 semantic-fact hint tables were removed in the worker_01
# consolidation: they existed only for the removed oracle decision procedure,
# which the final generator no longer contains. The independent verifier in
# tests/test_d08_artifact_generator.py re-derives dispositions from the
# typed-input reason codes per contract §6.1/§10.)
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
# Temporal interval algebra (contract §4.4 D08TemporalComparison).
# ---------------------------------------------------------------------------
TEMPORAL_RELATIONS = ("before", "after", "equal", "overlap", "contains", "contained_by")


# ===========================================================================
# Oracle: independently persisted, exact-hash-pinned IMMUTABLE INPUT.
# The final generator NEVER derives, infers, recomputes or rewrites medical
# expected leaves from typed_input/disposition/case specs/runtime (v0.6 §12:
# the catalog leaf keys are null placeholders; the real expected leaves exist
# only in the independent oracle). This module only:
#   (1) loads the pinned oracle and validates file/content hashes and schema,
#   (2) validates cross references between the pinned oracle and the catalog,
#   (3) assembles the registry + assertion DSL.
# There is no decision procedure, no authoring mode and no hidden fallback:
# every typed-fact-driven check below RAISES on mismatch and never produces an
# expected outcome. The independent semantic verifier for §13.3 lives in
# tests/test_d08_artifact_generator.py (it does not import this module).
# ===========================================================================
ORACLE_TOP_KEYS = ["artifact_kind", "case_count", "content_hash", "contract_semantic_hash",
                   "oracle_id", "ordered_expectations", "schema_version"]
EXPECTATION_KEYS = ["case_id", "fixture_id", "expected_leaf_set", "expected_source_leaf_set",
                    "expected_trace_leaf_set", "oracle_case_id"]

# Pinned immutable-input aliases (constants defined in the header).
PINNED_ORACLE_FILE_SHA256 = ORACLE_FILE_SHA256
PINNED_ORACLE_CONTENT_HASH = ORACLE_CONTENT_HASH


def load_oracle(catalog: dict[str, Any], oracle_path: Path | None = None) -> dict[str, Any]:
    """Load the persisted oracle as an immutable input.

    The oracle FILE hash is pinned as a literal constant: any reseal of the
    oracle (even one that recomputes its embedded content_hash consistently)
    changes the file bytes and fails closed before any registry assembly.
    """
    path = oracle_path or ORACLE
    raw = path.read_bytes()
    file_hash = sha256_bytes(raw)
    if file_hash != PINNED_ORACLE_FILE_SHA256:
        raise D08ArtifactError(
            "oracle_hash", "stale_hash",
            f"oracle file SHA-256 {file_hash} != pinned {PINNED_ORACLE_FILE_SHA256}")
    oracle = json.loads(raw.decode("utf-8"))
    validate_oracle(oracle, catalog, oracle_path=path)
    return oracle


def _primary_unit_kind(leaf: dict[str, Any]) -> str | None:
    """Unit kind of the primary (non-handoff) unit, if any."""
    i = 0
    primary: str | None = None
    while f"units.{i}.l1_disposition" in leaf:
        if not leaf.get(f"units.{i}.lineage_handoff"):
            primary = leaf.get(f"units.{i}.unit_kind") or primary
            break
        i += 1
    return primary


def check_oracle_catalog_crossrefs(case: dict[str, Any], expectation: dict[str, Any]) -> None:
    """Cross-reference validation between the PINNED oracle entry and the
    catalog case. Pure value-level comparisons between two independently
    persisted artifacts — nothing is derived or recomputed here.

    A typed-input mutation with catalog resealing that changes disposition,
    grain, ownership or visibility fails closed at this layer; the semantic
    mutations (cutoff/temporal/propagation) fail in the independent verifier.
    """
    case_id = case["case_id"]
    leaf = expectation["expected_leaf_set"]
    typed = case["typed_input"]
    disp = case["disposition"]
    # --- identity bijection (contract §12) -----------------------------------
    if expectation["fixture_id"] != case["fixture_id"]:
        raise D08ArtifactError("identity/duplicate", "bijection_drift",
                               f"{case_id} oracle fixture_id mismatch")
    if expectation["oracle_case_id"] != case["oracle_case_id"]:
        raise D08ArtifactError("identity/duplicate", "bijection_drift",
                               f"{case_id} oracle_case_id mismatch")
    # --- disposition label vs oracle leaf summary (both persisted values) ---
    if disp == CONSUME_ONLY_DISPOSITION:
        if leaf.get("unit_count", 0) != 0:
            raise D08ArtifactError("oracle_independence", "disposition_conflict",
                                   f"{case_id} consume_only but oracle unit_count != 0")
        for key in ("l2.risk_count", "l2.query_count", "l2.clue_count"):
            if leaf.get(key, 0) != 0:
                raise D08ArtifactError("oracle_independence", "disposition_conflict",
                                       f"{case_id} consume_only but oracle {key} != 0")
        if leaf.get("ownership.d08_action") != "consume_only":
            raise D08ArtifactError("oracle_independence", "disposition_conflict",
                                   f"{case_id} consume_only but oracle d08_action != consume_only")
    elif disp == "positive":
        if leaf.get("positive_count", 0) < 1:
            raise D08ArtifactError("oracle_independence", "disposition_conflict",
                                   f"{case_id} disposition positive but oracle positive_count == 0")
    elif disp == "negative":
        if leaf.get("negative_count", 0) < 1 and leaf.get("unit_count", 0) != 0:
            raise D08ArtifactError("oracle_independence", "disposition_conflict",
                                   f"{case_id} disposition negative but oracle has no negative/zero units")
    elif disp == "boundary":
        if leaf.get("boundary_count", 0) < 1:
            raise D08ArtifactError("oracle_independence", "disposition_conflict",
                                   f"{case_id} disposition boundary but oracle boundary_count == 0")
    elif disp == "not_applicable":
        if leaf.get("not_applicable_count", 0) < 1:
            raise D08ArtifactError("oracle_independence", "disposition_conflict",
                                   f"{case_id} disposition not_applicable but oracle not_applicable_count == 0")
    elif disp == "not_evaluable":
        if leaf.get("not_evaluable_count", 0) < 1 and leaf.get("integrity.stage") != "integrity_error":
            raise D08ArtifactError("oracle_independence", "disposition_conflict",
                                   f"{case_id} disposition not_evaluable but oracle has no not_evaluable unit")
    else:
        raise D08ArtifactError("schema_parse", "schema_error", f"{case_id} unknown disposition {disp}")
    # --- grain vs primary unit kind (both persisted values) ------------------
    if disp != CONSUME_ONLY_DISPOSITION and leaf.get("integrity.stage") != "integrity_error":
        primary_kind = _primary_unit_kind(leaf)
        if primary_kind is not None and primary_kind != case["grain"]:
            raise D08ArtifactError("oracle_independence", "grain_conflict",
                                   f"{case_id} catalog grain {case['grain']!r} != oracle primary "
                                   f"unit kind {primary_kind!r}")
    # --- ownership agreement (catalog owner_route vs oracle ownership) -------
    token = case["clinical_claim_token"]
    route_owner = case["owner_route"].get("owner_domain")
    if token in D08_OWNED_TOKENS:
        if leaf.get("ownership.owner_domain") != "D08":
            raise D08ArtifactError("oracle_independence", "owner_routing_conflict",
                                   f"{case_id} d08 token but oracle owner_domain != D08")
        if route_owner != "D08":
            raise D08ArtifactError("schema_parse", "schema_error",
                                   f"{case_id} d08 token but owner_route owner != D08")
    elif token == "d08_routing_or_coverage_gate":
        if leaf.get("ownership.d08_action") not in ("evaluate_and_own", "routing_gate", "context_only"):
            raise D08ArtifactError("oracle_independence", "owner_routing_conflict",
                                   f"{case_id} routing gate token but oracle action {leaf.get('ownership.d08_action')}")
    else:
        if leaf.get("ownership.d08_action") != "consume_only":
            raise D08ArtifactError("oracle_independence", "owner_routing_conflict",
                                   f"{case_id} consume-only token but oracle d08_action != consume_only")
    # --- positive-unit structural invariant (§11) ----------------------------
    i = 0
    while f"units.{i}.l1_disposition" in leaf:
        if leaf.get(f"units.{i}.l1_disposition") == "positive":
            if not (leaf.get(f"units.{i}.evidence_count") or 0) >= 1:
                raise D08ArtifactError("oracle_independence", "evidence_missing",
                                       f"{case_id} positive unit {i} lacks supporting evidence")
            if not (leaf.get(f"units.{i}.participant_count") or 0) >= 2:
                raise D08ArtifactError("oracle_independence", "participants_missing",
                                       f"{case_id} positive unit {i} lacks 2+ participating records")
        i += 1
    # --- integrity fail-closed agreement -------------------------------------
    if leaf.get("integrity.stage") == "integrity_error":
        if leaf.get("unit_count", 0) != 0:
            raise D08ArtifactError("oracle_independence", "integrity_conflict",
                                   f"{case_id} integrity_error must have zero units")
        if leaf.get("l2.risk_count", 0) != 0 or leaf.get("l2.query_count", 0) != 0:
            raise D08ArtifactError("oracle_independence", "integrity_conflict",
                                   f"{case_id} integrity_error must not emit risk/query")
    # --- visibility invariants (oracle leaf vs typed visibility facts) -------
    vis = typed.get("visibility_decision") or {}
    projectable = set(leaf.get("source.projectable_node_set") or [])
    blinded = set(vis.get("blinded_node_ids") or [])
    forbidden = set(vis.get("forbidden_node_ids") or [])
    evaluation = set(vis.get("evaluation_node_set") or [])
    if projectable & blinded:
        raise D08ArtifactError("hidden_leakage", "leak_detected",
                               f"{case_id} oracle projectable set leaks a blinded node")
    if projectable & forbidden:
        raise D08ArtifactError("hidden_leakage", "leak_detected",
                               f"{case_id} oracle projectable set leaks a forbidden node")
    if not projectable.issubset(evaluation):
        raise D08ArtifactError("hidden_leakage", "projectable_scope",
                               f"{case_id} oracle projectable set not subset of evaluation set")
    hidden_count = leaf.get("source.hidden_node_count")
    if hidden_count is not None and hidden_count != len(blinded | forbidden):
        raise D08ArtifactError("hidden_leakage", "hidden_count_mismatch",
                               f"{case_id} oracle hidden_node_count {hidden_count} != {len(blinded | forbidden)}")
    if leaf.get("source.disclosure_leak_present") is True:
        raise D08ArtifactError("hidden_leakage", "leak_detected",
                               f"{case_id} oracle flags a disclosure leak")


def validate_oracle(oracle: dict[str, Any], catalog: dict[str, Any],
                    oracle_path: Path | None = None) -> dict[str, dict[str, Any]]:
    """Schema/hash/identity/cross-reference validation of the pinned oracle."""
    expect_exact_keys(oracle, ORACLE_TOP_KEYS, "oracle top-level")
    if oracle["oracle_id"] != ORACLE_ID:
        raise D08ArtifactError("schema_parse", "schema_error", "oracle_id mismatch")
    if oracle["contract_semantic_hash"] != CONTRACT_SEMANTIC_HASH:
        raise D08ArtifactError("contract_semantic_hash", "semantic_hash_mismatch",
                               "oracle contract_semantic_hash != pinned v0.6")
    if oracle["content_hash"] != content_hash(oracle, "content_hash"):
        raise D08ArtifactError("canonical_hash", "stale_hash", "oracle content_hash mismatch")
    if oracle["content_hash"] != PINNED_ORACLE_CONTENT_HASH:
        raise D08ArtifactError("canonical_hash", "stale_hash",
                               f"oracle content_hash {oracle['content_hash']} != pinned "
                               f"{PINNED_ORACLE_CONTENT_HASH}")
    cases = catalog["cases"]
    if oracle["case_count"] != len(cases) or len(oracle["ordered_expectations"]) != len(cases):
        raise D08ArtifactError("identity/duplicate", "duplicate_identity", "oracle case count mismatch")
    by_id: dict[str, dict[str, Any]] = {}
    for expectation, case in zip(oracle["ordered_expectations"], cases):
        expect_exact_keys(expectation, EXPECTATION_KEYS, f"{expectation.get('case_id')} expectation")
        if expectation["case_id"] != case["case_id"]:
            raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                                   "oracle/catalog case_id mismatch")
        for key in ("expected_leaf_set", "expected_trace_leaf_set", "expected_source_leaf_set"):
            if not isinstance(expectation[key], dict) or not expectation[key]:
                raise D08ArtifactError("schema_parse", "schema_error",
                                       f"{expectation['case_id']} {key} empty")
        check_oracle_catalog_crossrefs(case, expectation)
        by_id[case["case_id"]] = expectation
    return by_id


# ---------------------------------------------------------------------------
# Registry: five-column bijection + closed DSL + non-circular replay manifest
# ---------------------------------------------------------------------------
REGISTRY_TOP_KEYS = ["artifact_kind", "bijection_audit", "catalog_hash", "content_hash",
                     "contract_semantic_hash", "dsl_schema_hash", "generator_hash",
                     "manifest_hash", "oracle_hash", "ordered_registry_core", "registry_id",
                     "replay_manifest", "schema_version"]
REGISTRY_ROW_KEYS = ["assertion_program_hash", "case_id", "entrypoint", "expected_leaf_set_hash",
                     "fixture_id", "manifest_case_id", "oracle_case_id", "substantive_input_hash",
                     "test_id"]
BIJECTION_COLUMNS = ["case_id", "fixture_id", "oracle_case_id", "manifest_case_id", "test_id"]
REPLAY_MANIFEST_KEYS = ["manifest_id", "pass_count", "byte_identical", "algorithm_version",
                        "artifact_hashes", "excluded_nondeterminism"]


def build_registry(catalog: dict[str, Any], oracle: dict[str, Any],
                   generator_source_hash: str) -> dict[str, Any]:
    """Assemble the registry + assertion DSL from the two pinned inputs.

    The replay manifest embeds ONLY external artifact hashes (contract,
    catalog, oracle, generator, DSL schema). The registry's own hash is never
    embedded anywhere inside the registry: content_hash uses the standard
    self-field convention (SHA-256 over the canonical object minus the
    content_hash field — same convention as catalog_hash and the oracle
    content_hash), validated exactly by validate_registry, the two-pass
    byte-identical replay, and the externally pinned registry hashes in the
    tests. No circular self-reference exists.
    """
    oracle_by_id = {e["case_id"]: e for e in oracle["ordered_expectations"]}
    rows: list[dict[str, Any]] = []
    for index, case in enumerate(catalog["cases"], start=1):
        expectation = oracle_by_id[case["case_id"]]
        leaf = expectation["expected_leaf_set"]
        clauses: list[dict[str, Any]] = []
        for leaf_set, value in (
                ("expected_leaf_set", expectation["expected_leaf_set"]),
                ("expected_trace_leaf_set", expectation["expected_trace_leaf_set"]),
                ("expected_source_leaf_set", expectation["expected_source_leaf_set"])):
            for path, v in sorted(value.items()):
                clauses.append({"clause_id": f"d08-assert-{len(clauses) + 1:03d}",
                                "leaf_set": leaf_set, "path": path, "op": "eq", "expected": v})
        # closed invariant clauses from the typed visibility facts
        typed = case["typed_input"]
        vis = typed.get("visibility_decision") or {}
        for nid in vis.get("blinded_node_ids") or []:
            clauses.append({"clause_id": f"d08-assert-{len(clauses) + 1:03d}",
                            "leaf_set": "expected_source_leaf_set",
                            "path": "source.projectable_node_set", "op": "not_contains", "expected": nid})
        for nid in vis.get("forbidden_node_ids") or []:
            clauses.append({"clause_id": f"d08-assert-{len(clauses) + 1:03d}",
                            "leaf_set": "expected_source_leaf_set",
                            "path": "source.projectable_node_set", "op": "not_contains", "expected": nid})
        if vis.get("projectable_node_set"):
            clauses.append({"clause_id": f"d08-assert-{len(clauses) + 1:03d}",
                            "leaf_set": "expected_source_leaf_set",
                            "path": "source.projectable_node_set", "op": "subset_of",
                            "expected": sorted(vis.get("evaluation_node_set") or [])})
        program_hash = sha256_text(canonical_json(clauses))
        row = {
            "assertion_program_hash": program_hash,
            "case_id": case["case_id"],
            "entrypoint": "d08.expected_outcome_oracle",
            "expected_leaf_set_hash": sha256_text(canonical_json(leaf)),
            "fixture_id": case["fixture_id"],
            "manifest_case_id": case["manifest_case_id"],
            "oracle_case_id": case["oracle_case_id"],
            "substantive_input_hash": typed["mutation_context"]["substantive_input_hash"],
            "test_id": f"d08-test-{index:03d}",
        }
        rows.append(row)
    manifest_hash = sha256_text(canonical_json(rows))
    audit = audit_bijection(rows, catalog, oracle)
    replay = {
        "manifest_id": "d08-replay-manifest-v1",
        "pass_count": 2,
        "byte_identical": True,
        "algorithm_version": UNIT_ALGORITHM_VERSION,
        "artifact_hashes": {
            "contract_semantic": CONTRACT_SEMANTIC_HASH,
            "catalog": catalog["catalog_hash"],
            "oracle": oracle["content_hash"],
            "generator": generator_source_hash,
            "dsl_schema": dsl_schema_hash(),
        },
        "excluded_nondeterminism": ["wall_clock", "pid", "mtime", "row_number"],
    }
    registry = {
        "artifact_kind": REGISTRY_ARTIFACT_KIND,
        "bijection_audit": audit,
        "catalog_hash": catalog["catalog_hash"],
        "content_hash": None,
        "contract_semantic_hash": CONTRACT_SEMANTIC_HASH,
        "dsl_schema_hash": dsl_schema_hash(),
        "generator_hash": generator_source_hash,
        "manifest_hash": manifest_hash,
        "oracle_hash": oracle["content_hash"],
        "ordered_registry_core": rows,
        "registry_id": REGISTRY_ID,
        "replay_manifest": replay,
        "schema_version": REGISTRY_SCHEMA_VERSION,
    }
    registry["content_hash"] = content_hash(registry, "content_hash")
    return registry


def audit_bijection(rows: list[dict[str, Any]], catalog: dict[str, Any],
                    oracle: dict[str, Any]) -> dict[str, Any]:
    by_case = {row["case_id"]: row for row in rows}
    if len(rows) != len(by_case):
        raise D08ArtifactError("identity/duplicate", "bijection_drift", "case_id column not unique")
    pairwise: dict[str, bool] = {}
    for col in BIJECTION_COLUMNS[1:]:
        vals = [row[col] for row in rows]
        pairwise[f"case_id_to_{col}"] = len(set(vals)) == len(rows)
    uniqueness: dict[str, int] = {col: len({row[col] for row in rows}) for col in BIJECTION_COLUMNS}
    from collections import Counter
    distribution = dict(Counter(case["family_id"] for case in catalog["cases"]))
    dup_groups = duplicate_substantive_check(catalog["cases"])
    oracle_ids = {e["case_id"] for e in oracle["ordered_expectations"]}
    failing = sorted(oracle_ids - set(by_case))
    integrity_count = sum(1 for e in oracle["ordered_expectations"]
                          if e["expected_leaf_set"].get("integrity.stage") == "integrity_error")
    passed = (all(pairwise.values()) and not failing
              and uniqueness["case_id"] == len(rows))
    audit = {
        "case_count": len(rows),
        "column_uniqueness": uniqueness,
        "duplicate_substantive_input_groups": {k: v for k, v in dup_groups.items()},
        "five_way_bijection_passed": passed,
        "integrity_error_case_count": integrity_count,
        "pairwise_bijections": pairwise,
        "reference_validation": {
            "checked_case_count": len(rows),
            "failing_problem_count": len(failing),
            "passed": not failing,
            "unresolved_oracle_case_ids": failing,
        },
        "row_distribution": distribution,
        "row_distribution_passed": all(distribution.get(fam, 0) >= floor for fam, floor in FAMILY_FLOORS.items()),
        "static_independence": audit_static_independence(catalog, oracle),
    }
    if not passed:
        raise D08ArtifactError("identity/duplicate", "bijection_drift",
                               "five-way column bijection failed (duplicate column value)")
    if failing:
        raise D08ArtifactError("identity/duplicate", "identity_ambiguous",
                               f"unresolved oracle case ids: {failing}")
    return audit


def audit_static_independence(catalog: dict[str, Any], oracle: dict[str, Any]) -> dict[str, Any]:
    """Oracle leaf paths/roots must be disjoint from typed-input envelope and
    deep keys (D07 pattern): an overlap would mean one artifact was derived by
    echoing the other. Value-level identifiers (stable/rule ids) legitimately
    appear in both, so the check is key-vocabulary only."""
    leaf_paths: set[str] = set()
    for expectation in oracle["ordered_expectations"]:
        for key in ("expected_leaf_set", "expected_trace_leaf_set", "expected_source_leaf_set"):
            leaf_paths.update(expectation[key])
    leaf_roots = {path.split(".")[0] for path in leaf_paths}
    section_keys = set(TYPED_INPUT_SECTION_KEYS)
    root_overlap = sorted(leaf_roots & section_keys)
    segment_overlap = sorted({seg for path in leaf_paths for seg in path.split(".")} & section_keys)
    typed_deep_keys: set[str] = set()
    for case in catalog["cases"]:
        def walk(value: Any) -> None:
            if isinstance(value, dict):
                for k, v in value.items():
                    typed_deep_keys.add(k)
                    walk(v)
            elif isinstance(value, list):
                for item in value:
                    walk(item)
        walk(case["typed_input"])
    deep_overlap = sorted(typed_deep_keys & leaf_roots)
    if root_overlap or segment_overlap or deep_overlap:
        raise D08ArtifactError(
            "oracle_independence", "vocabulary_overlap",
            f"oracle leaf vocabulary overlaps typed-input envelope: "
            f"roots={root_overlap} segments={segment_overlap} deep={deep_overlap}")
    return {
        "deep_key_overlap": deep_overlap,
        "leaf_root_overlap": root_overlap,
        "leaf_segment_overlap": segment_overlap,
        "oracle_leaf_path_count": len(leaf_paths),
        "typed_input_deep_key_count": len(typed_deep_keys),
        "vocabulary_disjoint": True,
    }


def validate_registry(registry: dict[str, Any], catalog: dict[str, Any],
                      oracle: dict[str, Any], generator_source_hash: str) -> None:
    expect_exact_keys(registry, REGISTRY_TOP_KEYS, "registry top-level")
    if registry["registry_id"] != REGISTRY_ID:
        raise D08ArtifactError("schema_parse", "schema_error", "registry_id mismatch")
    if registry["contract_semantic_hash"] != CONTRACT_SEMANTIC_HASH:
        raise D08ArtifactError("contract_semantic_hash", "semantic_hash_mismatch", "registry contract hash")
    if registry["catalog_hash"] != catalog["catalog_hash"]:
        raise D08ArtifactError("canonical_hash", "stale_hash", "registry catalog_hash mismatch")
    if registry["oracle_hash"] != oracle["content_hash"]:
        raise D08ArtifactError("canonical_hash", "stale_hash", "registry oracle_hash mismatch")
    if registry["generator_hash"] != generator_source_hash:
        raise D08ArtifactError("canonical_hash", "stale_hash", "registry generator_hash mismatch")
    if registry["dsl_schema_hash"] != dsl_schema_hash():
        raise D08ArtifactError("canonical_hash", "stale_hash", "registry dsl_schema_hash mismatch")
    # exact content_hash validation: SHA-256 over the canonical object minus the
    # content_hash field only (no other exclusion — the replay manifest is fully
    # included because it no longer embeds the registry's own hash)
    if registry["content_hash"] != content_hash(registry, "content_hash"):
        raise D08ArtifactError("canonical_hash", "stale_hash", "registry content_hash mismatch")
    replay = registry["replay_manifest"]
    expect_exact_keys(replay, REPLAY_MANIFEST_KEYS, "replay_manifest")
    artifact_hashes = replay.get("artifact_hashes") or {}
    if not isinstance(artifact_hashes, dict) or "registry" in artifact_hashes:
        raise D08ArtifactError("canonical_hash", "circular_self_hash",
                               "replay manifest must not embed the registry's own hash")
    for ext in ("contract_semantic", "catalog", "oracle", "generator", "dsl_schema"):
        if not isinstance(artifact_hashes.get(ext), str) or len(artifact_hashes[ext]) != 64:
            raise D08ArtifactError("canonical_hash", "stale_hash",
                                   f"replay manifest artifact hash {ext} missing/invalid")
    rows = registry["ordered_registry_core"]
    if len(rows) != len(catalog["cases"]):
        raise D08ArtifactError("identity/duplicate", "duplicate_identity", "registry row count mismatch")
    for row, case in zip(rows, catalog["cases"]):
        expect_exact_keys(row, REGISTRY_ROW_KEYS, f"{row.get('case_id')} registry row")
        for col in BIJECTION_COLUMNS:
            expected_col = {
                "case_id": case["case_id"], "fixture_id": case["fixture_id"],
                "oracle_case_id": case["oracle_case_id"], "manifest_case_id": case["manifest_case_id"],
                "test_id": f"d08-test-{int(case['case_id'].rsplit('-', 1)[-1]):03d}",
            }[col]
            if row[col] != expected_col:
                raise D08ArtifactError("identity/duplicate", "bijection_drift",
                                       f"{row['case_id']} column {col} mismatch")
    if registry["manifest_hash"] != sha256_text(canonical_json(rows)):
        raise D08ArtifactError("canonical_hash", "stale_hash", "registry manifest_hash mismatch")
    audit = registry["bijection_audit"]
    if not audit["five_way_bijection_passed"]:
        raise D08ArtifactError("identity/duplicate", "bijection_drift", "five-way bijection failed")
    if not audit["reference_validation"]["passed"]:
        raise D08ArtifactError("identity/duplicate", "identity_ambiguous", "oracle reference validation failed")
    if not audit["static_independence"]["vocabulary_disjoint"]:
        raise D08ArtifactError("oracle_independence", "vocabulary_overlap",
                               "oracle vocabulary overlaps typed input")


# ---------------------------------------------------------------------------
# Negative mutations (fail-closed, schema/hash/cross-reference level).
# Semantic mutations (wrong cutoff / contains-direction / time-missing /
# propagation) are enforced by the independent verifier in the test file.
# ---------------------------------------------------------------------------
NEGATIVE_MUTATION_NAMES = (
    "stale_contract_hash_reject",
    "missing_case_key_reject",
    "extra_case_key_reject",
    "wrong_owner_token_reject",
    "wrong_grain_reject",
    "waiver_fourth_state_reject",
    "hidden_leakage_reject",
    "bijection_drift_reject",
    "oracle_coupling_reject",
    "legacy_hash_reject",
    "oracle_tamper_reject",
    "catalog_tamper_reject",
    "catalog_reseal_reject",
    "registry_self_hash_reject",
)


def _clone(obj: Any) -> Any:
    return json.loads(canonical_json(obj))


def run_negative_mutations(catalog: dict[str, Any], oracle: dict[str, Any],
                           registry: dict[str, Any]) -> dict[str, str]:
    """Apply each negative mutation to a copy; assert it fails closed."""
    evidence: dict[str, str] = {}

    def expect_fail(name: str, fn, description: str) -> None:
        try:
            fn()
        except D08ArtifactError as exc:
            evidence[name] = f"FAILED-CLOSED {description}: {exc.error_class}/{exc.stage}"
        except SystemExit as exc:
            evidence[name] = f"FAILED-CLOSED {description}: SystemExit({exc.code})"
        except Exception as exc:  # noqa: BLE001 - unexpected failures are test defects
            raise D08ArtifactError(
                "negative_mutation",
                "unexpected_exception",
                f"{name} raised {type(exc).__name__} instead of an expected "
                "D08ArtifactError/SystemExit",
            ) from exc
        else:
            raise D08ArtifactError("negative_mutation", "mutation_not_rejected",
                                   f"{name} mutation was NOT rejected: {description}")

    # 1. stale contract hash -> validate_contract SystemExit
    def m_stale_contract() -> None:
        orig = CONTRACT_FILE_SHA256
        try:
            globals()["CONTRACT_FILE_SHA256"] = "0" * 64
            validate_contract()
        finally:
            globals()["CONTRACT_FILE_SHA256"] = orig
    expect_fail("stale_contract_hash_reject", m_stale_contract, "pinned contract hash != file hash")

    # 2/3. missing / extra case key -> schema rejection
    def m_missing_key() -> None:
        case = _clone(catalog["cases"][0])
        case.pop("fixture_hash")
        validate_case(case, 1)
    expect_fail("missing_case_key_reject", m_missing_key, "missing case key fixture_hash")

    def m_extra_key() -> None:
        case = _clone(catalog["cases"][0])
        case["rogue_key"] = True
        validate_case(case, 1)
    expect_fail("extra_case_key_reject", m_extra_key, "extra case key rogue_key")

    # 4. wrong owner token (consume-only token on an owned case) -> schema
    def m_wrong_owner() -> None:
        case = _clone(by_case_id(catalog, "D08-CASE-002"))
        case["clinical_claim_token"] = "d02_cm_indication_match"
        check_case_consistency(case)
    expect_fail("wrong_owner_token_reject", m_wrong_owner, "owned case with consume-only token")

    # 5. wrong grain (design label) -> oracle grain cross-reference conflict
    def m_wrong_grain() -> None:
        case = _clone(by_case_id(catalog, "D08-CASE-011"))
        case["grain"] = "per_left_anchor_slot"
        expectation = oracle["ordered_expectations"][10]
        check_oracle_catalog_crossrefs(case, expectation)
    expect_fail("wrong_grain_reject", m_wrong_grain, "per_explicit_rel_instance -> per_left_anchor_slot")

    # 6. waiver fourth state -> closed enum rejection
    def m_waiver_4th() -> None:
        case = _clone(by_case_id(catalog, "D08-CASE-230"))
        case["typed_input"]["waiver_handoffs"][0]["closure_state"] = "partially_closed"
        validate_typed_input(case["typed_input"], case["case_id"], case["family_id"])
    expect_fail("waiver_fourth_state_reject", m_waiver_4th, "closure_state fourth value")

    # 7. hidden leakage: a blinded node leaking into typed projectable set must
    #    fail the visibility schema check
    def m_hidden_leak() -> None:
        case = _clone(by_case_id(catalog, "D08-CASE-146"))
        vis = case["typed_input"]["visibility_decision"]
        vis["projectable_node_set"] = sorted(set(vis["projectable_node_set"]) | set(vis["blinded_node_ids"]))
        validate_typed_input(case["typed_input"], case["case_id"], case["family_id"])
    expect_fail("hidden_leakage_reject", m_hidden_leak, "blinded node must never be projectable")

    # 8. bijection drift: duplicate test_id must be rejected by the audit
    def m_bijection() -> None:
        rows = _clone(registry["ordered_registry_core"])
        rows[1]["test_id"] = rows[0]["test_id"]
        audit_bijection(rows, catalog, oracle)
    expect_fail("bijection_drift_reject", m_bijection, "duplicate test_id column")

    # 9. oracle/runtime coupling: an oracle leaf root smuggled into typed input
    def m_coupling() -> None:
        case = _clone(catalog["cases"][0])
        case["typed_input"]["trace"] = {"units": []}  # 'trace' is an oracle leaf root
        catalog2 = _clone(catalog)
        catalog2["cases"][0] = case
        audit_static_independence(catalog2, oracle)
    expect_fail("oracle_coupling_reject", m_coupling, "oracle leaf root key in typed input")

    # 10. legacy v0.5 hash token must be rejected when it leaks into artifacts
    def m_legacy() -> None:
        reject_legacy_contract_hash(catalog, oracle, registry)
        poisoned = _clone(catalog)
        poisoned["cases"][0]["typed_input"]["mutation_context"]["mutation_description"] += \
            f" legacy-hash {LEGACY_CONTRACT_SHA256}"
        reject_legacy_contract_hash(poisoned)
    expect_fail("legacy_hash_reject", m_legacy, "legacy v0.5 hash must never appear")

    # 11. oracle tamper (even with consistent embedded content_hash) -> the
    #     pinned FILE hash fails closed; the oracle is never rewritten
    def m_oracle_tamper() -> None:
        import tempfile
        with tempfile.TemporaryDirectory() as tmp:
            tampered_path = Path(tmp) / ORACLE.name
            tampered = _clone(oracle)
            tampered["ordered_expectations"][0]["expected_leaf_set"]["positive_count"] = 0
            tampered["content_hash"] = content_hash(tampered, "content_hash")
            tampered_path.write_text(canonical_json(tampered) + "\n", encoding="utf-8")
            load_oracle(catalog, tampered_path)
    expect_fail("oracle_tamper_reject", m_oracle_tamper,
                "resealed oracle must fail the pinned file-hash pin")

    # 12. catalog tamper: on-disk catalog differs from the assembled/pinned
    #     catalog -> fail closed before any oracle interaction
    def m_catalog_tamper() -> None:
        import tempfile
        with tempfile.TemporaryDirectory() as tmp:
            tampered = _clone(catalog)
            tampered["cases"][0]["typed_input"]["record_nodes"][0]["cutoff_decision"]["decision"] = "out_of_cutoff"
            tampered["cases"][0]["fixture_hash"] = sha256_text(canonical_json(tampered["cases"][0]["typed_input"]))
            tampered["catalog_hash"] = content_hash(tampered, "catalog_hash")
            payload = canonical_json(tampered).encode("utf-8")
            if sha256_bytes(payload) == CATALOG_FILE_SHA256:
                raise D08ArtifactError("negative_mutation", "mutation_not_rejected",
                                       "catalog tamper did not change bytes")
            # Materialize the resealed catalog at the exact path consumed by
            # render_artifacts.  The mutation must be rejected for its stale
            # pinned hash, never because the temporary file is absent.
            (Path(tmp) / CATALOG.name).write_bytes(payload)
            render_artifacts(verbose=False, out_dir=Path(tmp))
    expect_fail("catalog_tamper_reject", m_catalog_tamper,
                "typed-input mutation + catalog reseal must fail closed")

    # 13. catalog reseal alone (same mutation without touching the oracle):
    #     cross-reference validation must fail against the pinned oracle
    def m_catalog_reseal() -> None:
        case = _clone(by_case_id(catalog, "D08-CASE-002"))
        case["disposition"] = "positive"
        expectation = oracle["ordered_expectations"][1]
        check_oracle_catalog_crossrefs(case, expectation)
    expect_fail("catalog_reseal_reject", m_catalog_reseal,
                "resealed catalog disposition must conflict with pinned oracle")

    # 14. registry self-hash: replay manifest embedding the registry's own hash
    #     must be rejected (non-circular schema)
    def m_registry_self_hash() -> None:
        poisoned = _clone(registry)
        poisoned["replay_manifest"]["artifact_hashes"]["registry"] = poisoned["content_hash"]
        validate_registry(poisoned, catalog, oracle, registry["generator_hash"])
    expect_fail("registry_self_hash_reject", m_registry_self_hash,
                "replay manifest must not embed its own registry hash")

    return evidence


def by_case_id(catalog: dict[str, Any], case_id: str) -> dict[str, Any]:
    for case in catalog["cases"]:
        if case["case_id"] == case_id:
            return case
    raise KeyError(case_id)


def reject_legacy_contract_hash(*artifacts: dict[str, Any]) -> None:
    """Contract §13: no leftover v0.5 hash in any generated artifact."""
    for artifact in artifacts:
        if LEGACY_CONTRACT_SHA256 in canonical_json(artifact):
            raise D08ArtifactError("contract_semantic_hash", "legacy_hash_found",
                                   "legacy v0.5 contract hash leaked into a generated artifact")


# ---------------------------------------------------------------------------
# Render pipeline: catalog (assembled) + pinned oracle (loaded) + registry,
# double-pass byte consistency. The oracle is NEVER written by this generator.
# ---------------------------------------------------------------------------
def render_artifacts(verbose: bool = True, out_dir: Path | None = None) -> dict[str, Any]:
    def log(message: str) -> None:
        if verbose:
            print(message)

    log("D08 typed artifact generator (worker_01 consolidation)")
    log("=" * 72)
    validate_contract()
    log(f"contract file/semantic SHA-256: {CONTRACT_SEMANTIC_HASH}  OK (v0.6 pin)")

    catalog_path = out_dir / CATALOG.name if out_dir else CATALOG
    oracle_path = out_dir / ORACLE.name if out_dir else ORACLE
    registry_path = out_dir / REGISTRY.name if out_dir else REGISTRY

    # The assembled catalog MUST be byte-identical to the frozen catalog file
    # (pinned file hash). Any spec edit / typed-input mutation / catalog
    # reseal fails closed here, before the oracle is even loaded — so a
    # resealed catalog can never cause oracle rewriting.
    catalog_a = assemble_catalog()
    catalog_bytes = canonical_json(catalog_a).encode("utf-8")
    assembled_hash = sha256_bytes(catalog_bytes)
    if assembled_hash != CATALOG_FILE_SHA256:
        raise D08ArtifactError("catalog_hash", "stale_hash",
                               f"assembled catalog SHA-256 {assembled_hash} != pinned "
                               f"{CATALOG_FILE_SHA256} (typed-input mutation / spec drift)")
    if not catalog_path.exists() or sha256_bytes(catalog_path.read_bytes()) != CATALOG_FILE_SHA256:
        raise D08ArtifactError("catalog_hash", "stale_hash",
                               "on-disk catalog differs from the frozen catalog (tamper/reseal)")

    # The oracle is loaded from the pinned file (never derived, never written).
    oracle_a = load_oracle(catalog_a, oracle_path)
    generator_hash = sha256_bytes(Path(__file__).resolve().read_bytes())
    registry_a = build_registry(catalog_a, oracle_a, generator_hash)
    reject_legacy_contract_hash(catalog_a, oracle_a, registry_a)

    # pass B must be byte-identical for every artifact
    catalog_b = assemble_catalog()
    oracle_b = load_oracle(catalog_b, oracle_path)
    registry_b = build_registry(catalog_b, oracle_b, generator_hash)
    reject_legacy_contract_hash(catalog_b, oracle_b, registry_b)

    cases_a, _ = validate_catalog(catalog_a)
    oracle_by_id = validate_oracle(oracle_a, catalog_a, oracle_path)
    validate_registry(registry_a, catalog_a, oracle_a, generator_hash)
    _ = oracle_by_id

    bytes_a_c = canonical_json(catalog_a).encode("utf-8")
    bytes_b_c = canonical_json(catalog_b).encode("utf-8")
    bytes_a_o = canonical_json(oracle_a).encode("utf-8")
    bytes_b_o = canonical_json(oracle_b).encode("utf-8")
    bytes_a_r = canonical_json(registry_a).encode("utf-8")
    bytes_b_r = canonical_json(registry_b).encode("utf-8")
    if not (bytes_a_c == bytes_b_c and bytes_a_o == bytes_b_o and bytes_a_r == bytes_b_r):
        raise D08ArtifactError("replay", "drift", "double-pass byte mismatch (nondeterministic generator)")
    log(f"double-pass byte-identical: catalog {len(bytes_a_c)} B, oracle {len(bytes_a_o)} B, "
        f"registry {len(bytes_a_r)} B  OK")

    counts = distribution_check(cases_a)
    log("\nfamily distribution:")
    for fam, count in sorted(counts.items()):
        floor = FAMILY_FLOORS[fam]
        flag = "OK" if count >= floor else "BELOW FLOOR"
        log(f"  {fam:<38} {count:3d}  (floor {floor:2d}) {flag}")
    log(f"  {'TOTAL':<38} {len(cases_a):3d}  (>= {MIN_CASE_COUNT})")

    multi = duplicate_substantive_check(cases_a)
    if multi:
        log("\nsubstantive-input duplicate groups (same substantive -> same disposition required):")
        for h, ids in sorted(multi.items(), key=lambda kv: kv[1]):
            disps = {by_case_id(catalog_a, i)["disposition"] for i in ids}
            log(f"  {ids} -> disposition {sorted(disps)}  ({h[:16]}...)")

    evidence = run_negative_mutations(catalog_a, oracle_a, registry_a)
    log("\nnegative mutations (fail-closed):")
    for name in NEGATIVE_MUTATION_NAMES:
        log(f"  {name:<38} {evidence.get(name, 'MISSING')}")
    if len(evidence) != len(NEGATIVE_MUTATION_NAMES):
        missing = [n for n in NEGATIVE_MUTATION_NAMES if n not in evidence]
        raise D08ArtifactError("negative_mutation", "mutation_not_run", f"missing: {missing}")

    # Write ONLY catalog + registry. The oracle is immutable input and is never
    # written by this generator (proof target of the tests).
    for path, payload, label in ((catalog_path, catalog_a, "catalog"),
                                 (registry_path, registry_a, "registry")):
        payload_bytes = canonical_json(payload).encode("utf-8")
        path.write_bytes(payload_bytes)
        log(f"\nwrote {path} ({len(payload_bytes)} bytes)")
        reloaded = json.loads(path.read_text(encoding="utf-8"))
        if canonical_json(reloaded).encode("utf-8") != payload_bytes:
            raise D08ArtifactError("replay", "drift", f"{label} reload byte mismatch")
    validate_catalog(json.loads(catalog_path.read_text(encoding="utf-8")))
    validate_oracle(json.loads(oracle_path.read_text(encoding="utf-8")), catalog_a, oracle_path)
    validate_registry(json.loads(registry_path.read_text(encoding="utf-8")), catalog_a, oracle_a, generator_hash)
    log("reload validation  OK")

    log(f"\ncatalog_id : {catalog_a['catalog_id']}")
    log(f"case_count : {catalog_a['case_count']}   catalog_hash: {catalog_a['catalog_hash']}")
    log(f"oracle_id  : {oracle_a['oracle_id']}   content_hash: {oracle_a['content_hash']}   (pinned input)")
    log(f"registry_id: {registry_a['registry_id']}   content_hash: {registry_a['content_hash']}")
    log(f"dsl_schema_hash: {registry_a['dsl_schema_hash']}")
    log("worker_01 handoff (Codex):")
    log("  - oracle is an independently persisted, exact-hash-pinned IMMUTABLE input; the")
    log("    generator derives nothing and never writes it")
    log("  - registry replay manifest embeds only external artifact hashes (non-circular)")
    log("  - independent semantic verifier (233-case audit) lives in tests/test_d08_artifact_generator.py")
    return {"catalog": catalog_a, "oracle": oracle_a, "registry": registry_a,
            "negative_mutation_evidence": evidence}


# ---------------------------------------------------------------------------
# Render + CLI
# ---------------------------------------------------------------------------
def render_catalog(verbose: bool = True, out_dir: Path | None = None) -> dict[str, Any]:
    """Backward-compatible entry: render all three artifacts (catalog/registry;
    the oracle is a pinned input and is only validated)."""
    result = render_artifacts(verbose, out_dir)
    return result["catalog"]


def main() -> int:
    try:
        render_artifacts(verbose=True)
    except D08ArtifactError as exc:
        print(f"FAILED: {exc}", file=sys.stderr)
        return 1
    except SystemExit as exc:
        print(f"FAILED: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
